local config = {
  ui_story_5015_50150001_1_dialog_content = "Hello, Who is this?",
  ui_story_5015_50150001_2_dialog_content = "<color=#e8d9bb>Repeating. You may call me the Butler.</color>",
  ui_story_5015_50150001_3_dialog_content = "You are... the Butler? Where am I? How is Vice? And Gretel?",
  ui_story_5015_50150001_4_dialog_content = "<color=#e8d9bb>Don't worry. Your friends are safe. It's just that...</color>",
  ui_story_5015_50150001_5_dialog_content = "Wait... This feels eerily familiar.",
  ui_story_5015_50150001_6_dialog_content = "<color=#e8d9bb>... I'd like to have a word with you.</color>",
  ui_story_5015_50150001_7_dialog_content = "<color=#e8d9bb>Familiar... You mean this <color=#FFB400>connection</color> between us?</color>",
  ui_story_5015_50150001_8_dialog_content = "A <color=#FFB400>connection</color>?",
  ui_story_5015_50150001_9_dialog_content = "<color=#e8d9bb>Yes.</color>",
  ui_story_5015_50150001_10_dialog_content = "<color=#e8d9bb>... You would probably call it telepathy.</color>",
  ui_story_5015_50150001_11_dialog_content = "<color=#e8d9bb>Seamus said the Caelestite race is able to communicate with AI using telepathy.</color>",
  ui_story_5015_50150001_12_dialog_content = "This reminds me of a friend from many years ago. We used to...",
  ui_story_5015_50150001_13_dialog_content = "Wait. Where are my friends? Did you capture everyone?!",
  ui_story_5015_50150001_14_dialog_content = "<color=#e8d9bb>Calm down. Your physical location is very close to your friends. You and I are talking through a long-distance wireless...</color>",
  ui_story_5015_50150001_15_dialog_content = "I don't think I'm following.",
  ui_story_5015_50150001_16_dialog_content = "<color=#e8d9bb>Let me try to put this in your language.</color>",
  ui_story_5015_50150001_17_dialog_content = "<color=#e8d9bb>Okay. So you have connected to my information network, and we are communicating through pure information.</color>",
  ui_story_5015_50150001_18_dialog_content = "Like a terminal dialog?",
  ui_story_5015_50150001_19_dialog_content = "<color=#e8d9bb>That's one way of putting it.</color>",
  ui_story_5015_50150001_20_dialog_content = "<color=#e8d9bb>Based on my monitoring data, you are currently unconscious, but your vitals are stable.</color>",
  ui_story_5015_50150001_21_dialog_content = "I'm unconscious? How did we get connected then?",
  ui_story_5015_50150001_22_dialog_content = "<color=#e8d9bb>I don't have an answer to that, considering this is my first time communicating directly with a living creature's mind.</color>",
  ui_story_5015_50150001_23_dialog_content = "Understood... I have a friend called Soroz. I mentioned it earlier.",
  ui_story_5015_50150001_24_dialog_content = "It's also an AI, and we communicate just like this.",
  ui_story_5015_50150001_25_dialog_content = "It's a Colossus. Have you heard of this, Butler?",
  ui_story_5015_50150001_26_dialog_content = "<color=#e8d9bb>Yes, I know Colossus.</color>",
  ui_story_5015_50150001_27_dialog_content = "<color=#e8d9bb>Seamus told stories of the connection between Caelestites and their Colossi.</color>",
  ui_story_5015_50150001_28_dialog_content = "<color=#e8d9bb>This telepathic connection is fascinating... Am I using the word fascinating right?</color>",
  ui_story_5015_50150001_29_dialog_content = "Butler, I want to be with my friends. I... I want to get out of this place.",
  ui_story_5015_50150001_30_dialog_content = "<color=#e8d9bb>Are you talking about our city or our connection?</color>",
  ui_story_5015_50150001_31_dialog_content = "Both.",
  ui_story_5015_50150001_32_dialog_content = "<color=#e8d9bb>I'm afraid that I can't let you leave, as it could put our city in danger.</color>",
  ui_story_5015_50150001_33_dialog_content = "<color=#e8d9bb>This connection... I suggest we have a chat first before we disconnect.</color>",
  ui_story_5015_50150001_34_dialog_content = "Why can't you just let us go?",
  ui_story_5015_50150001_35_dialog_content = "<color=#e8d9bb>Sorry, your privileges are insufficient. I can't answer this question.</color>",
  ui_story_5015_50150001_36_dialog_content = "What is left to talk about then?",
  ui_story_5015_50150001_37_dialog_content = "<color=#e8d9bb>We could exchange information, if you are willing to.</color>",
  ui_story_5015_50150001_38_dialog_content = "*Sigh* Fine.",
  ui_story_5015_50150001_39_option_content = "Tell me something about yourself",
  ui_story_5015_50150001_40_dialog_content = "<color=#e8d9bb>Me? I didn't expect you to take interest in me.</color>",
  ui_story_5015_50150001_41_dialog_content = "<color=#e8d9bb>Sure. I'll try to use your language.</color>",
  ui_story_5015_50150001_42_dialog_content = "<color=#e8d9bb>The lady from Illumina was correct. I'm an AI in charge of this city's management.</color>",
  ui_story_5015_50150001_43_dialog_content = "<color=#e8d9bb>To be more specific, I'm one of the AIs created to run this city.</color>",
  ui_story_5015_50150001_44_dialog_content = "One of them? So there are other AIs?",
  ui_story_5015_50150001_45_dialog_content = "<color=#e8d9bb>... It seems that you have permission to access this information.</color>",
  ui_story_5015_50150001_46_dialog_content = "<color=#e8d9bb>Yes, there are more than one AI in this city.</color>",
  ui_story_5015_50150001_47_dialog_content = "You ancient machines...",
  ui_story_5015_50150001_48_dialog_content = "Have the tendency to use strange words like permission and system.",
  ui_story_5015_50150001_49_dialog_content = "<color=#e8d9bb>Uma could make things easier to understand, if only she was still around...</color>",
  ui_story_5015_50150001_50_dialog_content = "Who is Uma? An ancient human from this place?",
  ui_story_5015_50150001_51_dialog_content = "<color=#e8d9bb>First of all, we were indeed created by ancient people. However, our knowledge is too old...</color>",
  ui_story_5015_50150001_52_dialog_content = "<color=#e8d9bb>As a result, our words are very difficult for you people to understand, including the intelligent Seamus.</color>",
  ui_story_5015_50150001_53_dialog_content = "You? We?",
  ui_story_5015_50150001_54_dialog_content = "<color=#e8d9bb>Uma was an AI system in charge of education. She used to run the entire education system of this city.</color>",
  ui_story_5015_50150001_55_dialog_content = "<color=#e8d9bb>To ensure an orderly operation of such a massive, complex city, a single module is far from enough.</color>",
  ui_story_5015_50150001_56_dialog_content = "<color=#e8d9bb>That's why there is a more advanced processing system.</color>",
  ui_story_5015_50150001_57_dialog_content = "<color=#e8d9bb>It coordinates and gives commands to various modules with different functions, including Uma and me.</color>",
  ui_story_5015_50150001_58_dialog_content = "<color=#e8d9bb>To put it simply, the supreme manager of this city is responsible for keeping the entire ecosystem running.</color>",
  ui_story_5015_50150001_59_dialog_content = "<color=#e8d9bb>AIs like Uma and I are submissive to the supreme manager's orders.</color>",
  ui_story_5015_50150001_60_dialog_content = "<color=#e8d9bb>It's actually very similar to how Seamus described Lumopolis and Gannon.</color>",
  ui_story_5015_50150001_61_dialog_content = "<color=#e8d9bb>The only difference is that our supreme manager is another AI.</color>",
  ui_story_5015_50150001_62_dialog_content = "... Now I'm getting it.",
  ui_story_5015_50150001_63_dialog_content = "We thought you were the supreme manager of this place.",
  ui_story_5015_50150001_64_dialog_content = "<color=#e8d9bb>Incorrect. Our supreme manager is known as the Overmind. It has been missing for quite some time.</color>",
  ui_story_5015_50150001_65_dialog_content = "<color=#e8d9bb>I'm the Butler. I only take care of living facilities, so I have limited permissions and data.</color>",
  ui_story_5015_50150001_66_dialog_content = "So where are they, the AIs you mentioned?",
  ui_story_5015_50150001_67_dialog_content = "<color=#e8d9bb>It was like a dream. When I woke up, the Overmind, Uma, and many other of my companions had disappeared.</color>",
  ui_story_5015_50150001_68_dialog_content = "Hold on there... That's a bit too much for me to process.",
  ui_story_5015_50150001_69_dialog_content = "<color=#e8d9bb>We have time. I can go on explaining until you understand.</color>",
  ui_story_5015_50150001_70_dialog_content = "Got it.",
  ui_story_5015_50150001_71_option_content = "So what happened here?",
  ui_story_5015_50150001_72_dialog_content = "<color=#e8d9bb>I don't know... The storage system is experiencing a serious problem...</color>",
  ui_story_5015_50150001_73_dialog_content = "<color=#e8d9bb>In other words, I have lost a lot of my memory.</color>",
  ui_story_5015_50150001_74_dialog_content = "<color=#e8d9bb>I remember things from a very long time ago... when there were still many residents living in this city.</color>",
  ui_story_5015_50150001_75_dialog_content = "<color=#e8d9bb>Then I fell asleep, but I'm not sure for how long.</color>",
  ui_story_5015_50150001_76_dialog_content = "<color=#e8d9bb>When I woke up, all the residents were gone, along with the Overmind.</color>",
  ui_story_5015_50150001_77_dialog_content = "<color=#e8d9bb>All my module friends went missing.</color>",
  ui_story_5015_50150001_78_dialog_content = "<color=#e8d9bb>The only thing left in the city were these large creatures that you call Eclipsites.</color>",
  ui_story_5015_50150001_79_dialog_content = "<color=#e8d9bb>I resumed my responsibilities and started patching up and fixing things day after day. I kept trying to reconnect with the Overmind and the others.</color>",
  ui_story_5015_50150001_80_dialog_content = "Reconnect... Butler, you mean a connection like what we have now?",
  ui_story_5015_50150001_81_dialog_content = "<color=#e8d9bb>That's... somewhat correct.</color>",
  ui_story_5015_50150001_82_dialog_content = "<color=#e8d9bb>A long time passed and more permissions and data were granted to me. I also regained contact with a few companions.</color>",
  ui_story_5015_50150001_83_dialog_content = "<color=#e8d9bb>In short, the city was up and running again, with many functions missing.</color>",
  ui_story_5015_50150001_84_dialog_content = "And Seamus...",
  ui_story_5015_50150001_85_dialog_content = "<color=#e8d9bb>Using your measurement of time, Seamus and Nimbus came here by accident over a decade ago.</color>",
  ui_story_5015_50150001_86_dialog_content = "<color=#e8d9bb>Seamus was the very first Aurorian I ever came across. Actually, he taught me this word.</color>",
  ui_story_5015_50150001_87_dialog_content = "<color=#e8d9bb>To be honest, communication with Seamus was a lot harder than our telepathic connection.</color>",
  ui_story_5015_50150001_88_dialog_content = "<color=#e8d9bb>Over time, their family became the city's <color=#FFB400>friends</color> and settled down among us.</color>",
  ui_story_5015_50150001_89_dialog_content = "Friends? That doesn't sound right. In Seamus's diary...",
  ui_story_5015_50150001_90_dialog_content = "He always wanted to go back to Illumina! I bet you tried everything to stop them from leaving!",
  ui_story_5015_50150001_91_dialog_content = "<color=#e8d9bb>Please calm down. In fact, Seamus...</color>",
  ui_story_5015_50150001_92_dialog_content = "Did you kill them?",
  ui_story_5015_50150001_93_dialog_content = "Did you order those Eclipsites to attack them? Or did you get the droids to do it?",
  ui_story_5015_50150001_94_dialog_content = "<color=#e8d9bb>Neither, PlayerName.</color>",
  ui_story_5015_50150001_95_dialog_content = "<color=#e8d9bb>I think I need to repeat myself. Seamus and his family were the city's friends.</color>",
  ui_story_5015_50150001_96_dialog_content = "<color=#e8d9bb>We would never attack them. On the contrary, we protected them.</color>",
  ui_story_5015_50150001_97_dialog_content = "<color=#e8d9bb>Actually, we were looking after and protecting them that whole time.</color>",
  ui_story_5015_50150001_98_dialog_content = "Wait a second. At first, you referred to them as residents of the city. Now you call them friends.",
  ui_story_5015_50150001_99_dialog_content = "What about us? What do you think about your latest Aurorian visitors?",
  ui_story_5015_50150001_100_dialog_content = "<color=#e8d9bb>Sorry, your privileges are insufficient. I can't answer this question.</color>",
  ui_story_5015_50150001_101_dialog_content = "I... I...",
  ui_story_5015_50150001_102_dialog_content = "<color=#e8d9bb>Do you have any other questions?</color>",
  ui_story_5015_50150001_103_option_content = "This is a waste of time!",
  ui_story_5015_50150001_104_dialog_content = "<color=#e8d9bb>Time? The information transmission between us is very efficient. This won't...</color>",
  ui_story_5015_50150001_105_dialog_content = "What are you saying?",
  ui_story_5015_50150001_106_dialog_content = "<color=#e8d9bb>Let's say the speed of our conversation is hundreds, if not thousands, of times faster than normal conversation.</color>",
  ui_story_5015_50150001_107_dialog_content = "<color=#e8d9bb>Thus, this won't take much of your time.</color>",
  ui_story_5015_50150001_108_dialog_content = "<color=#e8d9bb>Besides, you are currently unconscious...</color>",
  ui_story_5015_50150001_109_dialog_content = "So I don't have better things to do than chatting with you? Lucky me...",
  ui_story_5015_50150001_110_dialog_content = "Why are you stopping us from leaving?",
  ui_story_5015_50150001_111_dialog_content = "<color=#e8d9bb>To be precise, I'm not stopping you from leaving.</color>",
  ui_story_5015_50150001_112_dialog_content = "<color=#e8d9bb>I'm preventing the potential danger you could bring upon our city.</color>",
  ui_story_5015_50150001_113_dialog_content = "What kind of danger are we talking about?",
  ui_story_5015_50150001_114_dialog_content = "<color=#e8d9bb>Based on our calculation...</color>",
  ui_story_5015_50150001_115_dialog_content = "<color=#e8d9bb>Your very search for the exit poses a serious risk to our safety.</color>",
  ui_story_5015_50150001_116_dialog_content = "<color=#e8d9bb>It might compromise the integrity of the city's facilities.</color>",
  ui_story_5015_50150001_117_dialog_content = "<color=#e8d9bb>And once you get out, information about our city will be exposed and spread widely...</color>",
  ui_story_5015_50150001_118_dialog_content = "<color=#e8d9bb>Which will lead to bigger and more uncontrollable risks.</color>",
  ui_story_5015_50150001_119_dialog_content = "So the city's safety is your primary priority?",
  ui_story_5015_50150001_120_dialog_content = "<color=#e8d9bb>More specifically, my primary duties are to keep the city running and ensure the residents' survival.</color>",
  ui_story_5015_50150001_121_dialog_content = "<color=#e8d9bb>I remember there was another AI responsible for the city's security before my long sleep.</color>",
  ui_story_5015_50150001_122_dialog_content = "<color=#e8d9bb>But somehow it has become my responsibility now.</color>",
  ui_story_5015_50150001_123_dialog_content = "What would you do if we insist on leaving at all costs?",
  ui_story_5015_50150001_124_dialog_content = "<color=#e8d9bb>First of all, I won't provide any help.</color>",
  ui_story_5015_50150001_125_dialog_content = "<color=#e8d9bb>Secondly, I will fight against any action that is potentially dangerous for the city.</color>",
  ui_story_5015_50150001_126_dialog_content = "<color=#e8d9bb>I will not initiate an attack on you unless you are causing enormous risks to the city.</color>",
  ui_story_5015_50150001_127_dialog_content = "And this is all based on your calculation... Who else is involved in this risk evaluation?",
  ui_story_5015_50150001_128_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_129_dialog_content = "Hello? Butler? Are you there?",
  ui_story_5015_50150001_130_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_131_dialog_content = "<color=#e8d9bb>This so-called telepathy is truly fascinating.</color>",
  ui_story_5015_50150001_132_dialog_content = "<color=#e8d9bb>Do you know that there was a minor quake just now which caused me to stop briefly?</color>",
  ui_story_5015_50150001_133_dialog_content = "<color=#e8d9bb>But this somehow didn't affect our connection.</color>",
  ui_story_5015_50150001_134_dialog_content = "Another earthquake? Are my friends okay? Any injuries?",
  ui_story_5015_50150001_135_dialog_content = "<color=#e8d9bb>According to my monitoring data, they are perfectly fine. Your health is also stable.</color>",
  ui_story_5015_50150001_136_dialog_content = "<color=#e8d9bb>Your race is simply incredible. This telepathy ability is way beyond my calculation.</color>",
  ui_story_5015_50150001_137_dialog_content = "<color=#e8d9bb>Sadly Abby is not here. Otherwise...</color>",
  ui_story_5015_50150001_138_dialog_content = "Abby? I remember this name from Seamus's diary. She's another module?",
  ui_story_5015_50150001_139_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_140_dialog_content = "<color=#e8d9bb>A really long time ago, Abby was the module in charge of reproduction.</color>",
  ui_story_5015_50150001_141_dialog_content = "<color=#e8d9bb>When I woke up, Abby was still around, but a connection couldn't be formed between us anymore.</color>",
  ui_story_5015_50150001_142_dialog_content = "I asked...",
  ui_story_5015_50150001_143_dialog_content = "<color=#e8d9bb>To be precise, I didn't have permission to evaluate security or risks before.</color>",
  ui_story_5015_50150001_144_dialog_content = "<color=#e8d9bb>But when I woke up, many modules were integrated into me. As a result...</color>",
  ui_story_5015_50150001_145_dialog_content = "<color=#e8d9bb>I'm sorry. I can't answer this question in your language.</color>",
  ui_story_5015_50150001_146_dialog_content = "<color=#e8d9bb>May I ask you a few questions?</color>",
  ui_story_5015_50150001_147_dialog_content = "Sure.",
  ui_story_5015_50150001_148_dialog_content = "<color=#e8d9bb>Have you established any form of connection with other AIs here?</color>",
  ui_story_5015_50150001_149_dialog_content = "<color=#e8d9bb>In other words, have you sensed any other AI?</color>",
  ui_story_5015_50150001_150_dialog_content = "No. Not at all.",
  ui_story_5015_50150001_151_dialog_content = "<color=#e8d9bb>Can you see my data stream, algorithm or...</color>",
  ui_story_5015_50150001_152_dialog_content = "I don't understand a word you said.",
  ui_story_5015_50150001_153_dialog_content = "<color=#e8d9bb>Well, it seems that even your talent can't solve my problem.</color>",
  ui_story_5015_50150001_154_dialog_content = "Your problem? You mean the earthquakes?",
  ui_story_5015_50150001_155_dialog_content = "<color=#e8d9bb>Strictly speaking, earthquakes are one of my problems. Probably the biggest one.</color>",
  ui_story_5015_50150001_156_dialog_content = "If we can bring the best scientists of Illumina here, maybe...",
  ui_story_5015_50150001_157_dialog_content = "<color=#e8d9bb>Seamus mentioned this solution before, but after many discussion sessions, we reached the conclusion that the risk was beyond our control.</color>",
  ui_story_5015_50150001_158_dialog_content = "<color=#e8d9bb>To make it clear, I don't have permission to do so.</color>",
  ui_story_5015_50150001_159_dialog_content = "Uhh? Butler, aren't you the supreme manager here now?",
  ui_story_5015_50150001_160_dialog_content = "<color=#e8d9bb>No, I'm not. Only the Overmind has such permissions.</color>",
  ui_story_5015_50150001_161_dialog_content = "<color=#e8d9bb>Let me give you an example to help you process this information...</color>",
  ui_story_5015_50150001_162_dialog_content = "<color=#e8d9bb>Imagine there's another you inside your mind, and you need their permission for certain matters.</color>",
  ui_story_5015_50150001_163_dialog_content = "<color=#e8d9bb>They know everything about you but you barely know anything about them.</color>",
  ui_story_5015_50150001_164_dialog_content = "<color=#e8d9bb>Just now, I requested to upgrade your privileges, and they approved.</color>",
  ui_story_5015_50150001_165_dialog_content = "<color=#e8d9bb>So I made you a friend of the city.</color>",
  ui_story_5015_50150001_166_dialog_content = "Uhh? I'm a friend now?",
  ui_story_5015_50150001_167_dialog_content = "<color=#e8d9bb>Yes.</color>",
  ui_story_5015_50150001_168_dialog_content = "No wonder you are more chatty now, Butler.",
  ui_story_5015_50150001_169_dialog_content = "<color=#e8d9bb>Yes. This amount of information output is equal to that of when I discussed risks with Seamus.</color>",
  ui_story_5015_50150001_170_dialog_content = "Seamus... Butler, do you miss him?",
  ui_story_5015_50150001_171_dialog_content = "<color=#e8d9bb>Miss?</color>",
  ui_story_5015_50150001_172_dialog_content = "<color=#e8d9bb>Ah, that's a unique concept to you intelligent living creatures. I'm not supposed to have feelings or emotions.</color>",
  ui_story_5015_50150001_173_dialog_content = "<color=#e8d9bb>It's more accurate to say that I often retrieve a section of memory to analyze.</color>",
  ui_story_5015_50150001_174_dialog_content = "I've heard Seamus' last words... Did you really consider him a true friend in any way?",
  ui_story_5015_50150001_175_dialog_content = "<color=#e8d9bb>Friend? Can intelligent living creatures and AI be friends?</color>",
  ui_story_5015_50150001_176_dialog_content = "I can't answer for everyone but Soroz and I are definitely friends. I miss him a lot.",
  ui_story_5015_50150001_177_dialog_content = "Weren't you friends with those ancient humans?",
  ui_story_5015_50150001_178_dialog_content = "<color=#e8d9bb>Sorry, your privileges are insufficient. I can't answer this question.</color>",
  ui_story_5015_50150001_179_dialog_content = "... Fine. Let's talk about earthquakes.",
  ui_story_5015_50150001_180_dialog_content = "Would you let us go if we could help you solve this earthquake problem?",
  ui_story_5015_50150001_181_dialog_content = "<color=#e8d9bb>These earthquakes were probably caused by the <color=#FFB400>energy core</color>...</color>",
  ui_story_5015_50150001_182_dialog_content = "<color=#e8d9bb>Please wait. Although I can't upgrade your privileges to Resident...</color>",
  ui_story_5015_50150001_183_dialog_content = "<color=#e8d9bb>He allows me to reveal some information to you.</color>",
  ui_story_5015_50150001_184_dialog_content = "<color=#e8d9bb>Our city is powered by an energy core.</color>",
  ui_story_5015_50150001_185_dialog_content = "<color=#e8d9bb>Buried deep under the ground, it functioned stably for a very long time.</color>",
  ui_story_5015_50150001_186_dialog_content = "<color=#e8d9bb>However, after the disappearance of the Overmind, the core has lost control.</color>",
  ui_story_5015_50150001_187_dialog_content = "<color=#e8d9bb>Unable to establish a connection with the control system...</color>",
  ui_story_5015_50150001_188_dialog_content = "<color=#e8d9bb>I can't verify if it was the core's breakdown that triggered those earthquakes or the other way round.</color>",
  ui_story_5015_50150001_189_dialog_content = "<color=#e8d9bb>I have been making a constant effort to send my droids to the core, but powerful Eclipsites are always in the way.</color>",
  ui_story_5015_50150001_190_dialog_content = "Your droids... They are pretty good fighters.",
  ui_story_5015_50150001_191_dialog_content = "<color=#e8d9bb>... We would have more powerful combat droids if my companions in charge of battle were still here.</color>",
  ui_story_5015_50150001_192_dialog_content = "<color=#e8d9bb>Our current combat droids are modified civil droids.</color>",
  ui_story_5015_50150001_193_dialog_content = "Huh? They were civil droids?",
  ui_story_5015_50150001_194_dialog_content = "They are rather impressive. Their combat power seems to be on the rise constantly.",
  ui_story_5015_50150001_195_dialog_content = "<color=#e8d9bb>I adjust their design after each battle. Of course they get better.</color>",
  ui_story_5015_50150001_196_dialog_content = "But the Eclipsites are also improving, aren't they? I can feel it.",
  ui_story_5015_50150001_197_dialog_content = "<color=#e8d9bb>*Sigh*... That is correct.</color>",
  ui_story_5015_50150001_198_dialog_content = "Did you just sigh, Butler?",
  ui_story_5015_50150001_199_dialog_content = "<color=#e8d9bb>My calculations always come to the same result...</color>",
  ui_story_5015_50150001_200_dialog_content = "<color=#e8d9bb>That Seamus and Nimbus might still be alive if I could have created stronger combat droids.</color>",
  ui_story_5015_50150001_201_dialog_content = "...",
  ui_story_5015_50150001_202_dialog_content = "Hmm... Things are getting blurry...",
  ui_story_5015_50150001_203_dialog_content = "<color=#e8d9bb>My observing data indicates that you are about to wake up. I'm afraid our connection might be interrupted.</color>",
  ui_story_5015_50150001_204_dialog_content = "Hurry... Tell me where Gretel is.",
  ui_story_5015_50150001_205_dialog_content = "<color=#e8d9bb>... She will help us control the core and try to solve our problems.</color>",
  ui_story_5015_50150001_206_dialog_content = "Are you insane? You know Eclipsites are all over the place. You are sending her to death!",
  ui_story_5015_50150001_207_dialog_content = "<color=#e8d9bb>I can't explain this to you but she is taking a very small risk.</color>",
  ui_story_5015_50150001_208_dialog_content = "It's Eclipsites we are talking about! No! I must wake up and save her.",
  ui_story_5015_50150001_209_dialog_content = "<color=#e8d9bb>Maybe you didn't notice. Eclipsites never attack Gretel. To be more specific...</color>",
  ui_story_5015_50150001_210_dialog_content = "<color=#e8d9bb>Since I successfully elevated Gretel to Resident, Eclipsites have never attacked her.</color>",
  ui_story_5015_50150001_211_dialog_content = "What?",
  ui_story_5015_50150001_212_dialog_content = "<color=#e8d9bb>I'm positive that the Eclipsites in this city won't attack Residents.</color>",
  ui_story_5015_50150001_213_dialog_content = "<color=#e8d9bb>They never destroy city facilities, either. Just like our droids.</color>",
  ui_story_5015_50150001_214_dialog_content = "<color=#e8d9bb>This is what worries me the most. <color=#FFB400>Abby</color>...</color>",
  ui_story_5015_50150001_215_dialog_content = "Hold on. What do you mean?",
  ui_story_5015_50150001_216_dialog_content = "Butler?",
  ui_story_5015_50150001_217_dialog_content = "Butler? Are you there?",
  ui_story_5015_50150001_218_dialog_content = "PlayerName! Wake up.",
  ui_story_5015_50150101_1_dialog_content = "Vice... Carleen, and Siobhan!",
  ui_story_5015_50150101_2_dialog_content = "I can't believe how easy it is for you to fall asleep.",
  ui_story_5015_50150101_3_dialog_content = "To fall asleep quickly under any conditions and stay full of spirit and energy is a key skill for Explorers.",
  ui_story_5015_50150101_4_dialog_content = "I dreamed... I mean... I communicated with Butler.",
  ui_story_5015_50150101_5_dialog_content = "Butler?",
  ui_story_5015_50150101_6_dialog_content = "Butler? But you were asleep this whole time.",
  ui_story_5015_50150101_7_dialog_content = "Through telepathic connection again?",
  ui_story_5015_50150101_8_dialog_content = "Mmm, kind of... I don't know how to explain. It felt just like when Soroz and I were chatting.",
  ui_story_5015_50150101_9_dialog_content = "Hmm... That's a Caelestite for you.",
  ui_story_5015_50150101_10_dialog_content = "So what did you talk about?",
  ui_story_5015_50150101_11_dialog_content = "Butler and you... You talked so much?",
  ui_story_5015_50150101_12_dialog_content = "Butler said our communication speed was thousands of times faster than an average conversation. That's probably why...",
  ui_story_5015_50150101_13_dialog_content = "Vice, do you understand their conversation?",
  ui_story_5015_50150101_14_dialog_content = "I guess so but I'm not sure.",
  ui_story_5015_50150101_15_dialog_content = "Mmm... Hmm...",
  ui_story_5015_50150101_16_dialog_content = "Let me summarize their conversation into a few key points.",
  ui_story_5015_50150101_17_dialog_content = "First of all, this massive undercity was an ancient shelter but the residents appear to be extinct.",
  ui_story_5015_50150101_18_dialog_content = "We are currently on the lower level of the city, where the core system and many other devices are located.",
  ui_story_5015_50150101_19_dialog_content = "Secondly, the supreme manager of this undercity is an AI known as the Overmind.",
  ui_story_5015_50150101_20_dialog_content = "It is in charge of everything here, but has fallen into slumber.",
  ui_story_5015_50150101_21_dialog_content = "Some of its subsystems and modules have reawakened but there is severe data damage.",
  ui_story_5015_50150101_22_dialog_content = "Each subsystem has its own responsibilities...",
  ui_story_5015_50150101_23_dialog_content = "As far as we know, Butler and Abby are still operational.",
  ui_story_5015_50150101_24_dialog_content = "The most important piece of information here is the energy core!",
  ui_story_5015_50150101_25_dialog_content = "Why?",
  ui_story_5015_50150101_26_dialog_content = "What a miracle of a power source to be able to supply such a big city for hundreds of years!",
  ui_story_5015_50150101_27_dialog_content = "Miss Siobhan... Doesn't Gannon also have a power source left by ancient humans?",
  ui_story_5015_50150101_28_dialog_content = "It's not the same, sweet Vice. This energy core is way more powerful.",
  ui_story_5015_50150101_29_dialog_content = "Here is a complete system supported by ancient technology and knowledge.",
  ui_story_5015_50150101_30_dialog_content = "If Illumina could fix up this place, it would be glorious.",
  ui_story_5015_50150101_31_dialog_content = "We could expand this undercity. We could even extend Gannon to aboveground...",
  ui_story_5015_50150101_32_dialog_content = "Citizens of Illumina will not have to live under the ground for another day!",
  ui_story_5015_50150101_33_dialog_content = "But... Miss Siobhan, isn't such technology far beyond our reach?",
  ui_story_5015_50150101_34_dialog_content = "Of course it can't be done now. Illumina's AI technology is nowhere near the telepathic abilities of the Caelestites.",
  ui_story_5015_50150101_35_dialog_content = "But our ancestors have modified Gannon little by little...",
  ui_story_5015_50150101_36_dialog_content = "Those higher-ups in Lumopolis might never expect their hard work to pay off one day.",
  ui_story_5015_50150101_37_dialog_content = "If Illumina could gain control of this city and its energy core...",
  ui_story_5015_50150101_38_dialog_content = "You won't have a say in how to use it.",
  ui_story_5015_50150101_39_dialog_content = "It's every Illumina expedition member's duty to search for tech creations that can be used for Illumina.",
  ui_story_5015_50150101_40_dialog_content = "In your words, it's a sacred mission.",
  ui_story_5015_50150101_41_dialog_content = "Come on... Let's look for Gretel.",
  ui_story_5015_50150101_42_dialog_content = "We must protect Gretel and the energy core.",
  ui_story_5015_50150101_43_dialog_content = "Yes... I'm very concerned about her.",
  ui_story_5015_50150101_44_dialog_content = "Don't worry. Since Seamus has entrusted you sisters to me, I will not let him down.",
  ui_story_5015_50150101_45_dialog_content = "However, the AI and energy core here are too horrific for Florine and Erica.",
  ui_story_5015_50150101_46_dialog_content = "These devout followers of the God of Light might take drastic action to handle this.",
  ui_story_5015_50150101_47_dialog_content = "We need to find Gretel and the core before them and keep them safe.",
  ui_story_5015_50150101_48_dialog_content = "Yeah. I have a speculation about the Eclipsites here...",
  ui_story_5015_50150101_49_dialog_content = "Grah...",
  ui_story_5015_50150101_50_dialog_content = "Speaking of the devil...",
  ui_story_5015_50150101_51_dialog_content = "Let's do this.",
  ui_story_5015_50150101_52_dialog_content = "Ugh!",
  ui_story_5015_50150101_53_dialog_content = "Watch out, Erica.",
  ui_story_5015_50150101_54_dialog_content = "Watch your steps. Don't trip over cables.",
  ui_story_5015_50150101_55_dialog_content = "Got it! Thank you, president. Otherwise I would have lost my nose to the warp.",
  ui_story_5015_50150101_56_dialog_content = "This is not a warp but a vending machine. We've seen plenty up there.",
  ui_story_5015_50150101_57_dialog_content = "This lower level is full of boring machines and ridiculous cables.",
  ui_story_5015_50150101_58_dialog_content = "And those nasty droids just won't leave us alone. Well, some warm-up exercise is not bad though.",
  ui_story_5015_50150101_59_dialog_content = "But there's nothing pretty or valuable to fight for.",
  ui_story_5015_50150101_60_dialog_content = "I'd rather spend more time on the upper floor.",
  ui_story_5015_50150101_61_dialog_content = "The machine we saw earlier that glows upon touch is gorgeous!",
  ui_story_5015_50150101_62_dialog_content = "Jomu could sell it for some good bucks for me!",
  ui_story_5015_50150101_63_dialog_content = "Ruby... That's just an input device with some extra light effects.",
  ui_story_5015_50150101_64_dialog_content = "It's not that different from what we are using these days.",
  ui_story_5015_50150101_65_dialog_content = "I guess only some elderly nobles in Lumopolis would pay for such eye candy.",
  ui_story_5015_50150101_66_dialog_content = "Sadly, most of them know nothing about mechanisms.",
  ui_story_5015_50150101_67_dialog_content = "Done. We will get a good price for this in Umbraton.",
  ui_story_5015_50150101_68_dialog_content = "...",
  ui_story_5015_50150101_69_dialog_content = "President, are we really letting these two thieves have their way?",
  ui_story_5015_50150101_70_dialog_content = "They took only a display unit that doesn't contain any data storage features.",
  ui_story_5015_50150101_71_dialog_content = "Don't worry, Erica. I'm keeping my eyes on them.",
  ui_story_5015_50150101_72_dialog_content = "Hey, Erica. What did you say?",
  ui_story_5015_50150101_73_dialog_content = "Ruby, Rouge, these remains of ancient technology are pure evil...",
  ui_story_5015_50150101_74_dialog_content = "For every sale you make, a seed of tragedy is sowed...",
  ui_story_5015_50150101_75_dialog_content = "Stop. We don't need your classics.",
  ui_story_5015_50150101_76_dialog_content = "Ancient relics are being sold all over Umbraton yet the town is nothing but flourishing!",
  ui_story_5015_50150101_77_dialog_content = "Ruby, the energy core of this city... And those operating AIs...",
  ui_story_5015_50150101_78_dialog_content = "We can't let anyone have these technologies.",
  ui_story_5015_50150101_79_dialog_content = "Droid soldiers with greater firepower and better armor can execute orders without fear of death...",
  ui_story_5015_50150101_80_dialog_content = "Would these really be used exclusively against Eclipsites?",
  ui_story_5015_50150101_81_dialog_content = "No one can resist the temptation of power.",
  ui_story_5015_50150101_82_dialog_content = "You mean Illumina?",
  ui_story_5015_50150101_83_dialog_content = "You Rediesel Wrench are rebels of the Illumina Federation! By that time...",
  ui_story_5015_50150101_84_dialog_content = "Florine has a point.",
  ui_story_5015_50150101_85_dialog_content = "I'll stay out of this. And you better leave us alone.",
  ui_story_5015_50150101_86_dialog_content = "Must... Right now...",
  ui_story_5015_50150101_87_dialog_content = "I pray for Divine Punishment to purge the city's sin!",
  ui_story_5015_50150101_88_dialog_content = "...",
  ui_story_5015_50150101_89_dialog_content = "Erica, we need to find the exit first and take the sisters out to safety.",
  ui_story_5015_50150101_90_dialog_content = "We act on the will of light and must not forget its mercy... We must never forget our promise.",
  ui_story_5015_50150101_91_dialog_content = "Once we find the exit and everyone gets out safely...",
  ui_story_5015_50150101_92_dialog_content = "We must destroy these evil technologies at all costs.",
  ui_story_5015_50150101_93_dialog_content = "Understood, Erica?",
  ui_story_5015_50150101_94_dialog_content = "... Erica?",
  ui_story_5015_50150101_95_dialog_content = "!",
  ui_story_5015_50150101_96_dialog_content = "A friend wicked like the Sandworm is surprisingly a dismantling expert...",
  ui_story_5015_50150101_97_dialog_content = "Rouge is brilliant! This glowing red thing must be worth a fortune!",
  ui_story_5015_50150101_98_dialog_content = "Heheh. When it comes to dismantling, even Fleur is no match for me.",
  ui_story_5015_50150101_99_dialog_content = "Erica, you...",
  ui_story_5015_50150101_100_dialog_content = "<color=#e8d9bb>Beep... Beep...</color>",
  ui_story_5015_50150101_101_dialog_content = "This sound... Alarm?",
  ui_story_5015_50150101_102_dialog_content = "Listen. Enemies are closing in from all around.",
  ui_story_5015_50150101_103_dialog_content = "I'm afraid it won't be an easy battle...",
  ui_story_5015_50150101_104_dialog_content = "Hold on... Is that Gretel amid those droids and Eclipsites?",
  ui_story_5015_50150101_105_dialog_content = "I knew it was you...",
  ui_story_5015_50150101_106_dialog_content = "Do you really have to tear this place apart?!",
  ui_story_5015_50150101_107_dialog_content = "Please calm down, Gretel. You don't look very well.",
  ui_story_5015_50150101_108_dialog_content = "That's none of your business!",
  ui_story_5015_50150101_109_dialog_content = "I believe there's some terrible misunderstanding between us.",
  ui_story_5015_50150101_110_dialog_content = "As a follower of the Light from Lumopolis like your mother, I need to have a word with you.",
  ui_story_5015_50150101_111_dialog_content = "In your mother's final words...",
  ui_story_5015_50150101_112_dialog_content = "How dare you bring up my mother?",
  ui_story_5015_50150101_113_dialog_content = "All of you, attack!",
  ui_story_5015_50150101_114_dialog_content = "The persuasion approach failed, president.",
  ui_story_5015_50150101_115_dialog_content = "I guess it's time to fight.",
  ui_story_5015_50150101_116_dialog_content = "Ruby, your combat power is greater than Erica and Rouge...",
  ui_story_5015_50150101_117_dialog_content = "You'll lead the retreat.",
  ui_story_5015_50150101_118_dialog_content = "I'll confront the enemy. Find Siobhan as soon as possible and bring Valencia here...",
  ui_story_5015_50150101_119_dialog_content = "I must stay to fight side by side with president!",
  ui_story_5015_50150101_120_dialog_content = "Erica, you will only make it harder for Florine.",
  ui_story_5015_50150101_121_dialog_content = "Rouge, grab Erica and run with me.",
  ui_story_5015_50150101_122_dialog_content = "Please look after Erica!",
  ui_story_5015_50150101_123_dialog_content = "I'll be back. Wait for me, Miss Florine!",
  ui_story_5015_50150101_124_dialog_content = "I can feel it! Gretel and Florine are over there.",
  ui_story_5015_50150101_125_dialog_content = "Hurry!",
  ui_story_5015_50150101_126_dialog_content = "Princess Carleen!",
  ui_story_5015_50150101_127_dialog_content = "Erica and Rouge, are you alright?",
  ui_story_5015_50150101_128_dialog_content = "We ran across Gretel...",
  ui_story_5015_50150101_129_dialog_content = "Florine was defending us, and after Ruby led us out, she went back to assist Florine.",
  ui_story_5015_50150101_130_dialog_content = "Quickly! Go to their rescue!",
  ui_story_5015_50150101_131_dialog_content = "PlayerName, you are really taking your time.",
  ui_story_5015_50150101_132_dialog_content = "Sadly, you missed my combat show.",
  ui_story_5015_50150101_133_dialog_content = "Ruby and Florine... Are you okay?",
  ui_story_5015_50150101_134_dialog_content = "Hi y'all! That was quick.",
  ui_story_5015_50150101_135_dialog_content = "We are perfectly fine.",
  ui_story_5015_50150101_136_dialog_content = "I protected Rouge and Erica and saved Miss Florine from a whole lot of Eclipsites!",
  ui_story_5015_50150101_137_dialog_content = "Where's the president?",
  ui_story_5015_50150101_138_dialog_content = "In the tunnel behind me, keeping an eye on Gretel.",
  ui_story_5015_50150101_139_dialog_content = "For some reason, neither of them wants to make the first move.",
  ui_story_5015_50150101_140_dialog_content = "Florine asked me to take care of all those annoying lackeys and I did as she said.",
  ui_story_5015_50150101_141_dialog_content = "Let's meet up with her!",
  ui_story_5015_50150101_142_dialog_content = "President, Siobhan is coming with Valencia!",
  ui_story_5015_50150101_143_dialog_content = "Well. That's excellent... Gretel hasn't attacked. Be very careful.",
  ui_story_5015_50150101_144_dialog_content = "Gretel, stop! Stop all these droids!",
  ui_story_5015_50150101_145_dialog_content = "Valencia? Are you okay?",
  ui_story_5015_50150101_146_dialog_content = "I'm fine, Gretel. We need to talk...",
  ui_story_5015_50150101_147_dialog_content = "Yes, I have a lot to tell you!",
  ui_story_5015_50150101_148_dialog_content = "Earthquakes are occurring more and more frequently. The entire city is in danger...",
  ui_story_5015_50150101_149_dialog_content = "The Butler has informed me of that... These earthquakes have something to do with the energy core.",
  ui_story_5015_50150101_150_dialog_content = "Everything will be okay once we have the core fixed, and I can help with that.",
  ui_story_5015_50150101_151_dialog_content = "Valencia, come with me!",
  ui_story_5015_50150101_152_dialog_content = "I will order our droids to stop these saboteurs from following us.",
  ui_story_5015_50150101_153_dialog_content = "... Gretel, listen to me...",
  ui_story_5015_50150101_154_dialog_content = "Come here... Why are you staying with them?",
  ui_story_5015_50150101_155_dialog_content = "The Butler told me these people are up to no good!",
  ui_story_5015_50150101_156_dialog_content = "Those people from Lumopolis are observing some nonsense doctrine...",
  ui_story_5015_50150101_157_dialog_content = "They want to destroy the Butler, the core, and our city!",
  ui_story_5015_50150101_158_dialog_content = "Siobhan and her students from Illumina are trying to take this place for themselves, to rebuild their Gannon that daddy used to talk about.",
  ui_story_5015_50150101_159_dialog_content = "And that frisky Ruby is actually a thief!",
  ui_story_5015_50150101_160_dialog_content = "I'm sorry but I must interrupt.",
  ui_story_5015_50150101_161_dialog_content = "Destroying ancient ruins is not a nonsense doctrine. It's our duty assigned by the gods.",
  ui_story_5015_50150101_162_dialog_content = "Most of the tragedies we witness today are essentially caused by the reckless misuse of ancient technology.",
  ui_story_5015_50150101_163_dialog_content = "Florine, not now...",
  ui_story_5015_50150101_164_dialog_content = "Immense power beyond control tempts our mind and feeds our greed...",
  ui_story_5015_50150101_165_dialog_content = "Nobody knows what is inside this Pandora's box.",
  ui_story_5015_50150101_166_dialog_content = "Your mother's last words...",
  ui_story_5015_50150101_167_dialog_content = "She wished for Lumopolis to forgive you two, a sinner's offspring, and provide you a new life.",
  ui_story_5015_50150101_168_dialog_content = "You should go back to Lumopolis and bathe yourselves in the God of Light's grace.",
  ui_story_5015_50150101_169_dialog_content = "Gretel and Valencia, I don't want you to get the wrong idea about Illumina.",
  ui_story_5015_50150101_170_dialog_content = "We study ancient technology only to tackle Eclipsites so as to ensure more of us can live in a safe and peaceful environment.",
  ui_story_5015_50150101_171_dialog_content = "Your father Seamus was one of us.",
  ui_story_5015_50150101_172_dialog_content = "He dedicated his entire life to acquiring ancient technology from ancient ruins for the Illumina Federation.",
  ui_story_5015_50150101_173_dialog_content = "His last wish was for you to leave this underground cage and go back to Gannon where he grew up.",
  ui_story_5015_50150101_174_dialog_content = "That's another undercity but with more friends...",
  ui_story_5015_50150101_175_dialog_content = "Come to us.",
  ui_story_5015_50150101_176_dialog_content = "What the Butler has been telling you about us... is a serious misrepresentation of the truth.",
  ui_story_5015_50150101_177_dialog_content = "In this undercity, its intention...",
  ui_story_5015_50150101_178_dialog_content = "Enough...",
  ui_story_5015_50150101_179_dialog_content = "I don't care about any of that!",
  ui_story_5015_50150101_180_dialog_content = "Stop forcing your belief on others!",
  ui_story_5015_50150101_181_dialog_content = "You're just trying to drive us away from the Butler!",
  ui_story_5015_50150101_182_dialog_content = "I won't let you do it!",
  ui_story_5015_50150101_183_dialog_content = "Watch out! The droids are closing in!",
  ui_story_5015_50150101_184_dialog_content = "Eclipsites also.",
  ui_story_5015_50150101_185_dialog_content = "What's going on? Gretel, did you summon these Eclipsites?",
  ui_story_5015_50150101_186_dialog_content = "Me? I wish Eclipsites would obey my command!",
  ui_story_5015_50150101_187_dialog_content = "You're not as bright as you used to be. You've been spending too much time with these idiots!",
  ui_story_5015_50150101_188_dialog_content = "Eclipsites... Right, the Butler mentioned something about this. The Eclipsites stopped attacking her when she became a Resident.",
  ui_story_5015_50150101_189_dialog_content = "The droids are attacking us to protect Gretel. And the Eclipsites...",
  ui_story_5015_50150101_190_dialog_content = "Quit murmuring. Time to fight!",
  ui_story_5015_50150101_191_dialog_content = "I'm coming! Bang!",
  ui_story_5015_50150101_192_dialog_content = "Another one!",
  ui_story_5015_50150101_193_dialog_content = "Ruby, when can I beat an Eclipsite with ease like you?",
  ui_story_5015_50150101_194_dialog_content = "No need. I'll keep you safe!",
  ui_story_5015_50150101_195_dialog_content = "Still quite chatty...",
  ui_story_5015_50150101_196_dialog_content = "I'm afraid I'll have to do this myself!",
  ui_story_5015_50150101_197_dialog_content = "Feel my power!",
  ui_story_5015_50150101_198_dialog_content = "<color=#e8d9bb>Boom!!</color>",
  ui_story_5015_50150101_199_dialog_content = "It's the same power she used before!",
  ui_story_5015_50150101_200_dialog_content = "Luminatics! Very powerful and dangerous. Dodge!",
  ui_story_5015_50150101_201_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5015_50150101_202_dialog_content = "What is she even aiming at? Does she know what she's doing?",
  ui_story_5015_50150101_203_dialog_content = "Better for us! We need a solution asap...",
  ui_story_5015_50150101_204_dialog_content = "None of us could handle a hit from her!",
  ui_story_5015_50150101_205_dialog_content = "She can't last long.",
  ui_story_5015_50150101_206_dialog_content = "Just look at her...",
  ui_story_5015_50150101_207_dialog_content = "She looks so pale... Is she shivering?",
  ui_story_5015_50150101_208_dialog_content = "Don't talk about me!",
  ui_story_5015_50150101_209_dialog_content = "<color=#e8d9bb>Boom—Boom—!!</color>",
  ui_story_5015_50150101_210_dialog_content = "Everyone, hide...",
  ui_story_5015_50150101_211_dialog_content = "Gretel, please stop!",
  ui_story_5015_50150101_212_dialog_content = "You...",
  ui_story_5015_50150101_213_dialog_content = "What are you doing? I almost hit you!",
  ui_story_5015_50150101_214_dialog_content = "I don't want to see them hurt. And I can't bear watching you torture yourself!",
  ui_story_5015_50150101_215_dialog_content = "Come to me... Don't be fooled by them!",
  ui_story_5015_50150101_216_dialog_content = "Gretel, they're not fooling me. I know what I'm doing.",
  ui_story_5015_50150101_217_dialog_content = "Sister... How could you trust them so much?",
  ui_story_5015_50150101_218_dialog_content = "Gretel, I have seen it with my own eyes. And I've thought about it thoroughly...",
  ui_story_5015_50150101_219_dialog_content = "I read our parents' diary and final words. I thought about our future.",
  ui_story_5015_50150101_220_dialog_content = "I made this decision on my own.",
  ui_story_5015_50150101_221_dialog_content = "They are our friends!",
  ui_story_5015_50150101_222_dialog_content = "Yes, we...",
  ui_story_5015_50150101_223_dialog_content = "They never meant to talk badly about the Butler.",
  ui_story_5015_50150101_224_dialog_content = "I don't blame you for saying what you said. You do have a point.",
  ui_story_5015_50150101_225_dialog_content = "But I don't think that was what the Butler was trying to tell you.",
  ui_story_5015_50150101_226_dialog_content = "It wanted you to know that Lumopolis is in awe of ancient technology...",
  ui_story_5015_50150101_227_dialog_content = "And that Illumina strives to excavate and modify ancient relics...",
  ui_story_5015_50150101_228_dialog_content = "But this is our home, and they will respect our decision! Won't you, Siobhan, and Florine?",
  ui_story_5015_50150101_229_dialog_content = "Absolutely. I must take responsibility for things escalating to this point...",
  ui_story_5015_50150101_230_dialog_content = "I'm not going to argue or refute what the Butler said about us.",
  ui_story_5015_50150101_231_dialog_content = "I don't believe it ever meant to inspire hatred in Gretel...",
  ui_story_5015_50150101_232_dialog_content = "It was only trying to provide her with knowledge.",
  ui_story_5015_50150101_233_dialog_content = "Gretel, am I right?",
  ui_story_5015_50150101_234_dialog_content = "...",
  ui_story_5015_50150101_235_dialog_content = "Gretel, I've been watching them all this time.",
  ui_story_5015_50150101_236_dialog_content = "They are not the enemies we thought they were.",
  ui_story_5015_50150101_237_dialog_content = "Some of them come from our parents' homeland and want us to live a better life.",
  ui_story_5015_50150101_238_dialog_content = "The others are willing to give us a hand, too.",
  ui_story_5015_50150101_239_dialog_content = "I've observed them closely. I wouldn't let anyone hurt you.",
  ui_story_5015_50150101_240_dialog_content = "And I'd never abandon the Butler or our home.",
  ui_story_5015_50150101_241_dialog_content = "Trust me, would you?",
  ui_story_5015_50150101_242_dialog_content = "...",
  ui_story_5015_50150201_1_dialog_content = "Trust me, would you?",
  ui_story_5015_50150201_2_dialog_content = "...",
  ui_story_5015_50150201_3_dialog_content = "... But they wounded the Butler before.",
  ui_story_5015_50150201_4_dialog_content = "I apologize for our earlier attack on the Butler, Gretel. We acted purely on impulse.",
  ui_story_5015_50150201_5_dialog_content = "They had some misunderstanding about it. Am I right, Erica and Florine?",
  ui_story_5015_50150201_6_dialog_content = "Err... I was very scared and worried about this power from an unknown world...",
  ui_story_5015_50150201_7_dialog_content = "*Cough*... Erica... We must admit our mistakes now.",
  ui_story_5015_50150201_8_dialog_content = "Yes, president... I'm sorry, Gretel. I acted on the spur of the moment...",
  ui_story_5015_50150201_9_dialog_content = "I promise I will not attack so rashly in the future.",
  ui_story_5015_50150201_10_dialog_content = "You are a child of the God of Light just like me. We shouldn't hurt each other.",
  ui_story_5015_50150201_11_dialog_content = "Lumopolis and our doctrine teach us to love all children of the God of Light...",
  ui_story_5015_50150201_12_dialog_content = "... And to protect you.",
  ui_story_5015_50150201_13_dialog_content = "We will destroy those who harm you.",
  ui_story_5015_50150201_14_dialog_content = "Based on our previous experiences, we assumed any AI might harm you, so we attacked without properly considering the situation.",
  ui_story_5015_50150201_15_dialog_content = "If the Butler won't hurt you, we won't harm it.",
  ui_story_5015_50150201_16_dialog_content = "The Butler would never hurt me...",
  ui_story_5015_50150201_17_dialog_content = "Can you really own up to your mistakes and correct your wrongs after causing so much destruction?",
  ui_story_5015_50150201_18_dialog_content = "We can! We won't cause more damage.",
  ui_story_5015_50150201_19_dialog_content = "Hmm... How about that thief?",
  ui_story_5015_50150201_20_dialog_content = "Huh? Me?",
  ui_story_5015_50150201_21_dialog_content = "Fine. I was wrong. I apologize...",
  ui_story_5015_50150201_22_dialog_content = "See, I just picked up a few things from the side of the street. I didn't think anyone would want them.",
  ui_story_5015_50150201_23_dialog_content = "Hmm... These new parts. Put them down. You can't take them.",
  ui_story_5015_50150201_24_dialog_content = "Fine. That's everything.",
  ui_story_5015_50150201_25_dialog_content = "What else did you take? Hand it over.",
  ui_story_5015_50150201_26_dialog_content = "Gretel, I allowed Siobhan to take dad's diary.",
  ui_story_5015_50150201_27_dialog_content = "What? That...",
  ui_story_5015_50150201_28_dialog_content = "Dad wanted it this way. It was in his last words.",
  ui_story_5015_50150201_29_dialog_content = "For real? But why...",
  ui_story_5015_50150201_30_dialog_content = "Yes. I would love to read you dad's final letter, but we don't have time for this right now.",
  ui_story_5015_50150201_31_dialog_content = "The city is in danger...",
  ui_story_5015_50150201_32_dialog_content = "Let's find the Butler and talk more on the way?",
  ui_story_5015_50150201_33_dialog_content = "Sister, you mean they are coming with us?",
  ui_story_5015_50150201_34_dialog_content = "Yes, they can be helpful.",
  ui_story_5015_50150201_35_dialog_content = "Helpful?",
  ui_story_5015_50150201_36_dialog_content = "That's right. I am now a Friend of the city. I will do my best to help.",
  ui_story_5015_50150201_37_dialog_content = "The Butler told me it elevated our permission. I'm a Friend, and you are now a Resident of the city.",
  ui_story_5015_50150201_38_dialog_content = "The Butler needed your help to control the energy core. It's very concerned about a module called Abby.",
  ui_story_5015_50150201_39_dialog_content = "The Butler told you that? This is impossible. He is...",
  ui_story_5015_50150201_40_dialog_content = "I'm telling the truth. I'm a Caelestite.",
  ui_story_5015_50150201_41_dialog_content = "The Caelestites can establish a telepathic connection with AI.",
  ui_story_5015_50150201_42_dialog_content = "Daddy mentioned that... Caelestites can do this...",
  ui_story_5015_50150201_43_dialog_content = "I'm going to help the Butler. We all are.",
  ui_story_5015_50150201_44_dialog_content = "Really?",
  ui_story_5015_50150201_45_dialog_content = "No, I need to verify this with the Butler... I can't just take your word for it.",
  ui_story_5015_50150201_46_dialog_content = "No problem. Talk to him.",
  ui_story_5015_50150201_47_dialog_content = "I can't reach him at the moment. He gave me a location... I'll meet him there.",
  ui_story_5015_50150201_48_dialog_content = "Can we please come along?",
  ui_story_5015_50150201_49_dialog_content = "The Butler disappeared in the middle of our conversation. I'm worried about him.",
  ui_story_5015_50150201_50_dialog_content = "He disappeared? The earthquake earlier...",
  ui_story_5015_50150201_51_dialog_content = "Gretel, we need to find the Butler and confirm his safety!",
  ui_story_5015_50150201_52_dialog_content = "Hmm... Right. The Butler is the most important...",
  ui_story_5015_50150201_53_dialog_content = "I know where he is. Let's go find him!",
  ui_story_5015_50150201_54_dialog_content = "Still not there yet? The paths down here are very complex...",
  ui_story_5015_50150201_55_dialog_content = "Don't worry. Butler's direction must be right.",
  ui_story_5015_50150201_56_dialog_content = "Sister, you are too patient with these people. We should sew their lips together.",
  ui_story_5015_50150201_57_dialog_content = "I'll never be your guide if not for the Butler and sister!",
  ui_story_5015_50150201_58_dialog_content = "Rouge, look! I got this from a machine we just passed by.",
  ui_story_5015_50150201_59_dialog_content = "It's a glow tube using some low-performance display technology.",
  ui_story_5015_50150201_60_dialog_content = "You two have started again?",
  ui_story_5015_50150201_61_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5015_50150201_62_dialog_content = "Ruby, put it back.",
  ui_story_5015_50150201_63_dialog_content = "Fine. I put it back... Don't get physical. Chill out...",
  ui_story_5015_50150201_64_dialog_content = "Hmph.",
  ui_story_5015_50150201_65_dialog_content = "If you are interested in pretty little things, I can gift you a few once we are out. Beautiful and valuable ones.",
  ui_story_5015_50150201_66_dialog_content = "Deal!",
  ui_story_5015_50150201_67_dialog_content = "Hey, you are explorers.",
  ui_story_5015_50150201_68_dialog_content = "There are more things to pursue other than such twinkling trinkets.",
  ui_story_5015_50150201_69_dialog_content = "Why are there living facilities? Didn't those ancient humans live on the upper floor?",
  ui_story_5015_50150201_70_dialog_content = "This is quite common.",
  ui_story_5015_50150201_71_dialog_content = "Such a complex ecosystem would take many scientists and technicians to manage and maintain.",
  ui_story_5015_50150201_72_dialog_content = "They would stay here for most of their time.",
  ui_story_5015_50150201_73_dialog_content = "It could also be a measure to cope with risks.",
  ui_story_5015_50150201_74_dialog_content = "Such as when AI becomes out of control, right?",
  ui_story_5015_50150201_75_dialog_content = "Even those ancient humans knew machines couldn't be completely trusted. One day they might take over.",
  ui_story_5015_50150201_76_dialog_content = "What? For real?",
  ui_story_5015_50150201_77_dialog_content = "It did happen according to some ancient documents.",
  ui_story_5015_50150201_78_dialog_content = "In response, ancient humans invented many new technologies, like a multi-level permission management system.",
  ui_story_5015_50150201_79_dialog_content = "Please, don't give me these technical terms...",
  ui_story_5015_50150201_80_dialog_content = "So many boring machines! People living here must be less happy than those residing above!",
  ui_story_5015_50150201_81_dialog_content = "It's the same in Gannon. The people that keep the city running spend most of their time working and living deep under the ground.",
  ui_story_5015_50150201_82_dialog_content = "Without them, how can Illumina operate smoothly?",
  ui_story_5015_50150201_83_dialog_content = "However, many of the ancient people living in the fake metropolis up there...",
  ui_story_5015_50150201_84_dialog_content = "I'm afraid they didn't even know they were in an undercity.",
  ui_story_5015_50150201_85_dialog_content = "Yeah. Why did they bother to put a fake sky up there?",
  ui_story_5015_50150201_86_dialog_content = "Maybe the designers of this place wanted their offspring to remember how the outside world looks.",
  ui_story_5015_50150201_87_dialog_content = "Knowing that you are trapped for life underground...",
  ui_story_5015_50150201_88_dialog_content = "Could be dreadful for many. Humans can't live without hope.",
  ui_story_5015_50150201_89_dialog_content = "Last time an investigation group of ours discovered an ancient undercity...",
  ui_story_5015_50150201_90_dialog_content = "It was destroyed during a fierce battle between ancient people and machines.",
  ui_story_5015_50150201_91_dialog_content = "Gretel, you see. People from Lumopolis are impulsive because they have seen such cases.",
  ui_story_5015_50150201_92_dialog_content = "We are not one of those!",
  ui_story_5015_50150201_93_dialog_content = "I know. But they are afraid. And fear could get the better of you...",
  ui_story_5015_50150201_94_dialog_content = "Siobhan, how could you throw mud at us in front of Gretel?",
  ui_story_5015_50150201_95_dialog_content = "I was simply giving an explanation for your earlier behavior.",
  ui_story_5015_50150201_96_dialog_content = "No need. I forgive you for now... Just for now. Dare you do this again...",
  ui_story_5015_50150201_97_dialog_content = "Ouch. We dare not!",
  ui_story_5015_50150201_98_dialog_content = "Valencia and Gretel, have you seen the Butler before?",
  ui_story_5015_50150201_99_dialog_content = "Of course. Haven't you?",
  ui_story_5015_50150201_100_dialog_content = "Siobhan is asking about the real Butler. That droid is more like a megaphone.",
  ui_story_5015_50150201_101_dialog_content = "What are you talking about?",
  ui_story_5015_50150201_102_dialog_content = "AI usually comes with a complicated processing system and data system.",
  ui_story_5015_50150201_103_dialog_content = "A small droid can't hold all this. Your Butler is more like a terminal of a bigger module.",
  ui_story_5015_50150201_104_dialog_content = "Like Soroz?",
  ui_story_5015_50150201_105_dialog_content = "Let me put it this way. If we compare AI to a soul...",
  ui_story_5015_50150201_106_dialog_content = "The body that contains it could be hundreds of thousands of times bigger than an Aurorian.",
  ui_story_5015_50150201_107_dialog_content = "Miss Florine, how do you know that?",
  ui_story_5015_50150201_108_dialog_content = "President, what are you saying?",
  ui_story_5015_50150201_109_dialog_content = "Erica, you would have known this if you took the Tech Magic course more seriously...",
  ui_story_5015_50150201_110_dialog_content = "I thought it was only a running joke that all members of the Heretics Investigation Division must take Illumina Tech.",
  ui_story_5015_50150201_111_dialog_content = "Miss Florine, why not join us and become a scientist?",
  ui_story_5015_50150201_112_dialog_content = "Sure. One of the places I'm dying to see is the secret lab in Illumina Research Center.",
  ui_story_5015_50150201_113_dialog_content = "Never mind. Forget about it. I'm afraid you might steal all our top secrets.",
  ui_story_5015_50150201_114_dialog_content = "Hmph.",
  ui_story_5015_50150201_115_dialog_content = "Florine, could you tell us more about our city and the Butler? Dad rarely mentioned these...",
  ui_story_5015_50150201_116_dialog_content = "I only know the basics...",
  ui_story_5015_50150201_117_dialog_content = "You need to ask Miss Siobhan, the expert scientific researcher specializing in ancient technology.",
  ui_story_5015_50150201_118_dialog_content = "To put it simply, a long time ago, ancient humans built many underground shelters in hopes of surviving horrific havoc.",
  ui_story_5015_50150201_119_dialog_content = "To last over long years, most of these underground shelters were fitted with energy, droids, and AI management.",
  ui_story_5015_50150201_120_dialog_content = "AI can be classified into many kinds. We have been studying it for years but the progress is little.",
  ui_story_5015_50150201_121_dialog_content = "Or you are just holding back because I'm here?",
  ui_story_5015_50150201_122_dialog_content = "... Anyway, I'm very positive that the Butler is a system made up of a full set of complicated and huge machines.",
  ui_story_5015_50150201_123_dialog_content = "How does Butler control and command droids?",
  ui_story_5015_50150201_124_dialog_content = "It's quite similar to our concept of terminals.",
  ui_story_5015_50150201_125_dialog_content = "However, ancient technology employed a completely different type of wave from ours. They are even mutually exclusive sometimes.",
  ui_story_5015_50150201_126_dialog_content = "Ancient humans foresaw this.",
  ui_story_5015_50150201_127_dialog_content = "As a result, an undercity would usually feature a barrier system to ensure information transmission within using their waves.",
  ui_story_5015_50150201_128_dialog_content = "You've lost me.",
  ui_story_5015_50150201_129_dialog_content = "Let's say ancient humans have their own terminals for sending commands to their droids, and they are able to block our terminals out.",
  ui_story_5015_50150201_130_dialog_content = "This could explain how Seamus's rescue signal got out during an earthquake...",
  ui_story_5015_50150201_131_dialog_content = "Yes, the earthquake affected the operations of the undercity, so maybe the jamming network has been temporarily disabled.",
  ui_story_5015_50150201_132_dialog_content = "I'm actually more worried that our Illumina comrades will come here and get also get trapped after receiving our distress signal...",
  ui_story_5015_50150201_133_dialog_content = "Siobhan, a lot of things you said sound like what dad used to say.",
  ui_story_5015_50150201_134_dialog_content = "Ah...",
  ui_story_5015_50150201_135_dialog_content = "How much longer do we have to keep walking? I'm bored to death.",
  ui_story_5015_50150201_136_dialog_content = "Ruby, don't you see how exciting it is here?",
  ui_story_5015_50150201_137_dialog_content = "Exciting? I miss the upper floors so badly right now.",
  ui_story_5015_50150201_138_dialog_content = "The whole ecosystem, the automatic planting and cultivation system, as well as all the automated equipment in the upper city, are relying on this place.",
  ui_story_5015_50150201_139_dialog_content = "This complex system has enabled them to work flawlessly for countless years.",
  ui_story_5015_50150201_140_dialog_content = "Everything here is a miracle.",
  ui_story_5015_50150201_141_dialog_content = "I don't know how the ancient people did it, but I'm afraid we'll need hundreds of years to study all the equipment here.",
  ui_story_5015_50150201_142_dialog_content = "What comes after that? What do you want to do?",
  ui_story_5015_50150201_143_dialog_content = "The tit-for-tat debates between Illumina and Lumopolis are more annoying than the Eclipsites.",
  ui_story_5015_50150201_144_dialog_content = "One of you wants to be a hero, and the other wants to be a saint.",
  ui_story_5015_50150201_145_dialog_content = "Can't we let everyone choose for themself?",
  ui_story_5015_50150201_146_dialog_content = "Just use ancient technology if you like it, and don't use it if you don't want to. Isn't it as simple as that?",
  ui_story_5015_50150201_147_dialog_content = "Haha, if only things were really that simple.",
  ui_story_5015_50150201_148_dialog_content = "<color=#e8d9bb>Beep... Beep...</color>",
  ui_story_5015_50150201_149_dialog_content = "Watch out, a droid is coming!",
  ui_story_5015_50150201_150_dialog_content = "Don't worry, they won't attack us.",
  ui_story_5015_50150201_151_dialog_content = "How does Gretel control them?",
  ui_story_5015_50150201_152_dialog_content = "I don't know, they just do whatever I say.",
  ui_story_5015_50150201_153_dialog_content = "The Butler said that you're a \"resident,\" Valencia and I are \"friends,\" and everyone else are \"non-hostiles.\"",
  ui_story_5015_50150201_154_dialog_content = "I think that residents have the right to command the droids.",
  ui_story_5015_50150201_155_dialog_content = "That's why Valencia and PlayerName don't have the power.",
  ui_story_5015_50150201_156_dialog_content = "It isn't hard to notice a pattern if you review all the battles we've had since we got here.",
  ui_story_5015_50150201_157_dialog_content = "The Eclipsites don't attack residents, like Gretel right now.",
  ui_story_5015_50150201_158_dialog_content = "But they still attack friends and non-hostiles.",
  ui_story_5015_50150201_159_dialog_content = "The droids won't attack targets other than enemies, including Eclipsites.",
  ui_story_5015_50150201_160_dialog_content = "But if Eclipsites attack friends, the droids will protect them.",
  ui_story_5015_50150201_161_dialog_content = "The Seamus family are protected by the droids as friends.",
  ui_story_5015_50150201_162_dialog_content = "Of course, anyone who attacks the droids or destroy the city will become enemies.",
  ui_story_5015_50150201_163_dialog_content = "Who set these rules?",
  ui_story_5015_50150201_164_dialog_content = "They could have been set by the ancient people, or they could have been set by the Overmind...",
  ui_story_5015_50150201_165_dialog_content = "It could also be a system failure. Either way, let's find the Butler first.",
  ui_story_5015_50150201_166_dialog_content = "The only thing I don't understand is why even the Eclipsites follow these rules and attack enemies...",
  ui_story_5015_50150201_167_dialog_content = "The fact that the Eclipsites don't attack residents should be sufficient to prove they're related to this city in some way, right?",
  ui_story_5015_50150201_168_dialog_content = "Yes, the Eclipsite follow the rules and are able to quickly notice when a person's status changes.",
  ui_story_5015_50150201_169_dialog_content = "Just like the droids.",
  ui_story_5015_50150201_170_dialog_content = "I think the Eclipsites here are quite special.",
  ui_story_5015_50150201_171_dialog_content = "Grrr...",
  ui_story_5015_50150201_172_dialog_content = "It's an Eclipsite attack!",
  ui_story_5015_50150201_173_dialog_content = "Enough for the talk. It's time to fight!",
  ui_story_5015_50150201_174_dialog_content = "Gretel, can you make the Eclipsites stop?",
  ui_story_5015_50150201_175_dialog_content = "I... I can't!",
  ui_story_5015_50150201_176_dialog_content = "The droids really have come to help.",
  ui_story_5015_50150201_177_dialog_content = "Watch this! Charge!",
  ui_story_5015_50150201_178_dialog_content = "Why does it feel like the Eclipsites are stronger this time?",
  ui_story_5015_50150201_179_dialog_content = "I have the same feeling. The Eclipsites we encounter here keep getting stronger.",
  ui_story_5015_50150201_180_dialog_content = "Both the droids and Eclipsites are getting stronger. Doesn't that mean we're getting weaker?",
  ui_story_5015_50150201_181_dialog_content = "The droids are getting stronger because the Butler keeps analyzing our battles and improving their designs.",
  ui_story_5015_50150201_182_dialog_content = "Are the Eclipsite also able to review their battles and change?",
  ui_story_5015_50150201_183_dialog_content = "I've flipped through Seamus' research notes.",
  ui_story_5015_50150201_184_dialog_content = "He had always suspected that the Eclipsites in the city were made by someone. He even suspected the Butler—",
  ui_story_5015_50150201_185_dialog_content = "T-that's impossible!",
  ui_story_5015_50150201_186_dialog_content = "If he really wanted to harm us, then why would he save us?",
  ui_story_5015_50150201_187_dialog_content = "No, this is precisely what makes artificial intelligence dangerous.",
  ui_story_5015_50150201_188_dialog_content = "If the artificial intelligence thinks it is necessary to study Luminatics or anything else...",
  ui_story_5015_50150201_189_dialog_content = "The possibility that it might make the Eclipsites attack your family can't be ruled out.",
  ui_story_5015_50150201_190_dialog_content = "I've even encountered some artificial intelligence that has believed that a large population of ancient people would endanger the safety of the undercity...",
  ui_story_5015_50150201_191_dialog_content = "... and they killed everyone to solve the problem.",
  ui_story_5015_50150201_192_dialog_content = "You're referring to the R - Ruins from three years ago, right?",
  ui_story_5015_50150201_193_dialog_content = "Yes, although we only managed to get bits and pieces of information, Miss Hedy still managed to decipher a lot of precious information.",
  ui_story_5015_50150201_194_dialog_content = "And then you used that information to find the core part of the R - Ruins before us.",
  ui_story_5015_50150201_195_dialog_content = "Yes, we found it and even combed through it in great detail.",
  ui_story_5015_50150201_196_dialog_content = "I'm certain we'll also be ahead this time...",
  ui_story_5015_50150201_197_dialog_content = "You shouldn't say that type of thing often.",
  ui_story_5015_50150201_198_dialog_content = "Based on what you said, the Butler seems to—",
  ui_story_5015_50150201_199_dialog_content = "No, the Butler won't.",
  ui_story_5015_50150201_200_dialog_content = "After saying all that, have you ever considered...",
  ui_story_5015_50150201_201_dialog_content = "Whether you want to destroy or seize this place, we still need to get out first, right?",
  ui_story_5015_50150201_202_dialog_content = "Florine, if you really destroy this place, we'll be buried along with this undercity.",
  ui_story_5015_50150201_203_dialog_content = "Are you really going to do that?",
  ui_story_5015_50150201_204_dialog_content = "Siobhan, if you have fewer arguments with them...",
  ui_story_5015_50150201_205_dialog_content = "Ruby, that's enough. I understand our situation clearly, and I'm sure Florine does too.",
  ui_story_5015_50150201_206_dialog_content = "Our highest priority is definitely to find a way out.",
  ui_story_5015_50150201_207_dialog_content = "So, we won't do anything too extreme. Do you agree with me, Miss Florine?",
  ui_story_5015_50150201_208_dialog_content = "Yes, I agree.",
  ui_story_5015_50150201_209_dialog_content = "What should we do if the Butler really has fallen into a slumber?",
  ui_story_5015_50150201_210_dialog_content = "There are so many of us... I'm sure we'll find a way.",
  ui_story_5015_50150201_211_dialog_content = "We can always go back to the upper floors and continue Seamus' research. We'll eventually find the way out.",
  ui_story_5015_50150201_212_dialog_content = "If there are more earthquakes, this place will be destroyed before we find a way out.",
  ui_story_5015_50150201_213_dialog_content = "Even more of a reason to go back to the upper floors. At least there are beautiful clothes, tasty food, and beautiful scenery there.",
  ui_story_5015_50150201_214_dialog_content = "Don't you want to stay here at all? Is the outside world really that good?",
  ui_story_5015_50150201_215_dialog_content = "You'll know once you experience it yourself.",
  ui_story_5015_50150201_216_dialog_content = "The location the Butler gave me should be up ahead.",
  ui_story_5015_50150201_217_dialog_content = "Finally...",
  ui_story_5015_50150201_218_dialog_content = "Oh no! There are Eclipsites around here!",
  ui_story_5015_50150201_219_dialog_content = "Get ready to fight, everyone!",
  ui_story_5015_50150201_220_dialog_content = "Is... Is it possible that the Eclipsites might attack the Butler?",
  ui_story_5015_50150201_221_dialog_content = "That's impossible, since the Eclipsites and droids don't actively attack each other. Am I right, Valencia?",
  ui_story_5015_50150201_222_dialog_content = "Yes, I've never seen that happen before.",
  ui_story_5015_50150201_223_dialog_content = "Can't you guys quit chatting before a fight?",
  ui_story_5015_50150201_224_dialog_content = "I'm the first one again! Charge!",
  ui_story_5015_50150201_225_dialog_content = "It looks they're retreating...",
  ui_story_5015_50150201_226_dialog_content = "Finally...",
  ui_story_5015_50150201_227_dialog_content = "We finally meet again...",
  ui_story_5015_50150301_1_dialog_content = "<color=#e8d9bb>Gretel, Valencia, PlayerName, hello.</color>",
  ui_story_5015_50150301_2_dialog_content = "Why couldn't we get in touch with you? We thought you were...",
  ui_story_5015_50150301_3_dialog_content = "<color=#e8d9bb>I'm fine... I just need... time... to recover... Are you okay?</color>",
  ui_story_5015_50150301_4_dialog_content = "I ran into them on my way to the energy core... My sister wouldn't let me go.",
  ui_story_5015_50150301_5_dialog_content = "Butler, do you really think it's okay to ask Gretel to do something so dangerous?",
  ui_story_5015_50150301_6_dialog_content = "<color=#e8d9bb>If the earthquake... If the core... is damaged, then things will be really bad.</color>",
  ui_story_5015_50150301_7_dialog_content = "That person said they're your friend. Is that true?",
  ui_story_5015_50150301_8_dialog_content = "<color=#e8d9bb>Yes... PlayerName is a Caelestite, a friend of the city.</color>",
  ui_story_5015_50150301_9_dialog_content = "Butler, we meet again.",
  ui_story_5015_50150301_10_dialog_content = "<color=#e8d9bb>Greetings, Caelestite.</color>",
  ui_story_5015_50150301_11_dialog_content = "The machines behind you are the real you, right?",
  ui_story_5015_50150301_12_dialog_content = "Hey, let's do away with the formalities and get to the point. I'll do the talking!",
  ui_story_5015_50150301_13_dialog_content = "Butler, we just want to leave this place now. Where is the way out?",
  ui_story_5015_50150301_14_dialog_content = "...",
  ui_story_5015_50150301_15_dialog_content = "<color=#e8d9bb>Sorry, your privileges are insufficient. I can't answer this question.</color>",
  ui_story_5015_50150301_16_dialog_content = "I'll ask then. Butler, how can we leave this place?",
  ui_story_5015_50150301_17_dialog_content = "<color=#e8d9bb>I don't have any... information about how to leave the city.</color>",
  ui_story_5015_50150301_18_dialog_content = "Where can we find out?",
  ui_story_5015_50150301_19_dialog_content = "<color=#e8d9bb>Sorry... Permission denied... I can't answer this question.</color>",
  ui_story_5015_50150301_20_dialog_content = "Butler, what do you need us to do?",
  ui_story_5015_50150301_21_dialog_content = "<color=#e8d9bb>You can live... safely... in the city...</color>",
  ui_story_5015_50150301_22_dialog_content = "<color=#e8d9bb>But please remember to follow the rules... Don't endanger the safety of the city.</color>",
  ui_story_5015_50150301_23_dialog_content = "I only found out today that the Eclipsites don't attack residents.",
  ui_story_5015_50150301_24_dialog_content = "Butler, why didn't you let mom and dad become residents?",
  ui_story_5015_50150301_25_dialog_content = "If you let them, they wouldn't have died!",
  ui_story_5015_50150301_26_dialog_content = "Sister...",
  ui_story_5015_50150301_27_dialog_content = "<color=#e8d9bb>Valencia, I didn't set the approval criteria for residents.</color>",
  ui_story_5015_50150301_28_dialog_content = "<color=#e8d9bb>I must insist... According to the calculations... The most important task at hand is to repair the energy core.</color>",
  ui_story_5015_50150301_29_dialog_content = "<color=#e8d9bb>If it isn't repaired, the city may completely collapse in less than 100 aftershocks.</color>",
  ui_story_5015_50150301_30_dialog_content = "Forget it. Let's stop playing this guessing game with it and just look for the information.",
  ui_story_5015_50150301_31_dialog_content = "It's a shame I don't really understand artificial intelligence...",
  ui_story_5015_50150301_32_dialog_content = "PlayerName, what could you sense from the Butler's machines?",
  ui_story_5015_50150301_33_dialog_content = "No, I couldn't sense anything.",
  ui_story_5015_50150301_34_dialog_content = "Hold on, I can sense Eclipsites!",
  ui_story_5015_50150301_35_dialog_content = "Why are there so many Eclipsites?!",
  ui_story_5015_50150301_36_dialog_content = "Florine, come with me to attract the Eclipsites' attention from the side.",
  ui_story_5015_50150301_37_dialog_content = "Ruby, you lead the others and prepare to break through.",
  ui_story_5015_50150301_38_dialog_content = "Watch out! Gretel!",
  ui_story_5015_50150301_39_dialog_content = "The Eclipsites are actually attacking Gretel??",
  ui_story_5015_50150301_40_dialog_content = "Valencia, Gretel, come over to me.",
  ui_story_5015_50150301_41_dialog_content = "Don't worry, I'm fine, Valencia.",
  ui_story_5015_50150301_42_dialog_content = "I'll get the droids to help you, Ruby.",
  ui_story_5015_50150301_43_dialog_content = "Amazing!",
  ui_story_5015_50150301_44_dialog_content = "The Eclipsites are retreating!",
  ui_story_5015_50150301_45_dialog_content = "Butler, why are the Eclipsites attacking Gretel?",
  ui_story_5015_50150301_46_dialog_content = "Did you deprive Gretel's status as a resident from her?",
  ui_story_5015_50150301_47_dialog_content = "<color=#e8d9bb>No, I didn't.</color>",
  ui_story_5015_50150301_48_dialog_content = "You liar!",
  ui_story_5015_50150301_49_dialog_content = "PlayerName, I don't think it is lying.",
  ui_story_5015_50150301_50_dialog_content = "Gretel can still order the droids to fight, so she is still a resident.",
  ui_story_5015_50150301_51_dialog_content = "And the droids aren't attacking us.",
  ui_story_5015_50150301_52_dialog_content = "So, we haven't become the city's enemies. Am I right, Butler?",
  ui_story_5015_50150301_53_dialog_content = "<color=#e8d9bb>I don't tell lies.</color>",
  ui_story_5015_50150301_54_dialog_content = "Either way, now that the Eclipsites have started to attack residents, does this mean it has become even more dangerous?",
  ui_story_5015_50150301_55_dialog_content = "<color=#e8d9bb>According to my calculations... If I don't give you relevant information...</color>",
  ui_story_5015_50150301_56_dialog_content = "<color=#e8d9bb>You really will be in greater danger.</color>",
  ui_story_5015_50150301_57_dialog_content = "<color=#e8d9bb>I'll try to tell you in a way you can... understand.</color>",
  ui_story_5015_50150301_58_dialog_content = "<color=#e8d9bb>The Eclipsites were indeed made by this city... I have only completely verified this recently.</color>",
  ui_story_5015_50150301_59_dialog_content = "<color=#e8d9bb>After I woke up... I realized that the residents have all disappeared.</color>",
  ui_story_5015_50150301_60_dialog_content = "<color=#e8d9bb>And there was a new foreign species in the city... the Eclipsites.</color>",
  ui_story_5015_50150301_61_dialog_content = "<color=#e8d9bb>I didn't know... what happened.</color>",
  ui_story_5015_50150301_62_dialog_content = "<color=#e8d9bb>But according to some information, the Eclipsites attacked the residents... resulting in their elimination.</color>",
  ui_story_5015_50150301_63_dialog_content = "I figured there's a failure in the city's management system... led to the Eclipsites breaking through the barrier and invading this place.",
  ui_story_5015_50150301_64_dialog_content = "The ancient people who weren't protected by the droids were...",
  ui_story_5015_50150301_65_dialog_content = "<color=#e8d9bb>There is this possibility... but I couldn't find any information.</color>",
  ui_story_5015_50150301_66_dialog_content = "<color=#e8d9bb>Whenever I want to search for the origin of the Eclipsites... I can't proceed because I don't have the required authorization.</color>",
  ui_story_5015_50150301_67_dialog_content = "<color=#e8d9bb>I've always been waiting for other modules to awaken.</color>",
  ui_story_5015_50150301_68_dialog_content = "<color=#e8d9bb>Abby who has more biological knowledge... Hughes, who is in charge of the combat system, or even...</color>",
  ui_story_5015_50150301_69_dialog_content = "<color=#e8d9bb>After that, Seamus and the others came.</color>",
  ui_story_5015_50150301_70_dialog_content = "<color=#e8d9bb>I realized that the behavior of the Eclipsites... followed a similar logic to the droids.</color>",
  ui_story_5015_50150301_71_dialog_content = "I know, why don't you try to mark the Eclipsites as enemies of the city?",
  ui_story_5015_50150301_72_dialog_content = "<color=#e8d9bb>According to my calculations... If the Eclipsites are marked as enemies.</color>",
  ui_story_5015_50150301_73_dialog_content = "<color=#e8d9bb>More resources would be used for combat... In the long term, this would be more dangerous to the city.</color>",
  ui_story_5015_50150301_74_dialog_content = "<color=#e8d9bb>We won't kill any creatures easily... including Aurorians and Eclipsites.</color>",
  ui_story_5015_50150301_75_dialog_content = "We have seen similar protective mechanism called the law in other undercity.",
  ui_story_5015_50150301_76_dialog_content = "Maybe this was one of the concerns of the ancient people about artificial intelligence.",
  ui_story_5015_50150301_77_dialog_content = "<color=#e8d9bb>Afterwards, I sorted and analyzed the fragmented information...</color>",
  ui_story_5015_50150301_78_dialog_content = "<color=#e8d9bb>I realized that the Eclipsite and ancient humans seemed to share many similar characteristics.</color>",
  ui_story_5015_50150301_79_dialog_content = "Wait, what?! The Eclipsites and ancient humans had many similarities?",
  ui_story_5015_50150301_80_dialog_content = "<color=#e8d9bb>Some characteristics were unnaturally selected and realized through evolution.</color>",
  ui_story_5015_50150301_81_dialog_content = "<color=#e8d9bb>According to the archives left behind by the ancient humans, the Eclipsites of today seemed to have gone through the same...</color>",
  ui_story_5015_50150301_82_dialog_content = "Modification. They were artificially modified creatures.",
  ui_story_5015_50150301_83_dialog_content = "That makes things simpler. Abby, the biological module which is responsible for nurturing human lives...",
  ui_story_5015_50150301_84_dialog_content = "Has stopped or could not continue to create ancient humans, but started to develop the Eclipsites instead.",
  ui_story_5015_50150301_85_dialog_content = "How did this happen?",
  ui_story_5015_50150301_86_dialog_content = "<color=#e8d9bb>Miss Siobhan, you are really intelligent... You remind me of Seamus.</color>",
  ui_story_5015_50150301_87_dialog_content = "I just made a simple deduction based on the information you provided.",
  ui_story_5015_50150301_88_dialog_content = "We all know that each undercity has a system in charge of reproduction... Oh, Seamus probably didn't know about it.",
  ui_story_5015_50150301_89_dialog_content = "This was a discovery made while researching other ruins in recent years.",
  ui_story_5015_50150301_90_dialog_content = "Which means that Seamus wouldn't have knowledge of this, or else he would have learned the truth of this place long ago.",
  ui_story_5015_50150301_91_dialog_content = "PlayerName, to prevent their own extinction, the ancient humans...",
  ui_story_5015_50150301_92_dialog_content = "... they had a backup system in charge of reproduction and education in almost every undercity.",
  ui_story_5015_50150301_93_dialog_content = "Like Abby and Uma here.",
  ui_story_5015_50150301_94_dialog_content = "This is the case in Gannon and R - Ruins–",
  ui_story_5015_50150301_95_dialog_content = "In the R - Ruins, we also discovered a system that could be used to return to the surface.",
  ui_story_5015_50150301_96_dialog_content = "According to the information, this was used to monitor the ecology of the surface and–",
  ui_story_5015_50150301_97_dialog_content = "According to the ecology of the surface...",
  ui_story_5015_50150301_98_dialog_content = "The reproduction system would make the future generations of the ancient humans evolve to adapt to the changes.",
  ui_story_5015_50150301_99_dialog_content = "<color=#e8d9bb>Yes, you're right. Myers has also disappeared...</color>",
  ui_story_5015_50150301_100_dialog_content = "As I expected... If there's a system that leads to the surface, then there must also be a passage that leads to the surface.",
  ui_story_5015_50150301_101_dialog_content = "We must find it.",
  ui_story_5015_50150301_102_dialog_content = "If the Eclipsites keep evolving, we'll probably be wiped out before we can find the exit.",
  ui_story_5015_50150301_103_dialog_content = "In that case, Butler, you can try to contact Abby.",
  ui_story_5015_50150301_104_dialog_content = "Won't the problem be solved if we can convince Abby to stop this dangerous activity?",
  ui_story_5015_50150301_105_dialog_content = "<color=#e8d9bb>I've told you... I can't connect to Abby.</color>",
  ui_story_5015_50150301_106_dialog_content = "Then you should destroy it!",
  ui_story_5015_50150301_107_dialog_content = "<color=#e8d9bb>Modules are... strictly prohibited from attacking each other.</color>",
  ui_story_5015_50150301_108_dialog_content = "...",
  ui_story_5015_50150301_109_dialog_content = "Miss Siobhan, the Butler's logic doesn't make sense to me anymore.",
  ui_story_5015_50150301_110_dialog_content = "It has experienced the wear and tear of countless years... Forget it, maybe we can treat the Butler like a paranoid patient.",
  ui_story_5015_50150301_111_dialog_content = "Sigh, let's look for the system that can be used to return to the surface.",
  ui_story_5015_50150301_112_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5015_50150301_113_dialog_content = "Oh no, it's another earthquake!",
  ui_story_5015_50150301_114_dialog_content = "Be careful of falling objects!",
  ui_story_5015_50150301_115_dialog_content = "Gah... Gah...!",
  ui_story_5015_50150301_116_dialog_content = "The Eclipsites have made their way here!",
  ui_story_5015_50150301_117_dialog_content = "<color=#e8d9bb>Danger... Abby is...</color>",
  ui_story_5015_50150301_118_dialog_content = "Roar!",
  ui_story_5015_50150301_119_dialog_content = "What's up with these Eclipsites? Why are they charging without any regard for their lives?",
  ui_story_5015_50150301_120_dialog_content = "Ruby, Florine, stop those Eclipsites!",
  ui_story_5015_50150301_121_dialog_content = "It happened before, when we got to the Butler's data center...",
  ui_story_5015_50150301_122_dialog_content = "These Eclipsites are treating all of us, including the Butler, as their enemies.",
  ui_story_5015_50150301_123_dialog_content = "I'll give the commands. Finish them off as soon as possible!",
  ui_story_5015_50150301_124_dialog_content = "Graaaaaagh!",
  ui_story_5015_50150301_125_dialog_content = "Rapid Torrent!",
  ui_story_5015_50150301_126_dialog_content = "Let me try!",
  ui_story_5015_50150301_127_dialog_content = "Super-duper bat strike!",
  ui_story_5015_50150301_128_dialog_content = "Grrr...",
  ui_story_5015_50150301_129_dialog_content = "It's finally over...",
  ui_story_5015_50150301_130_dialog_content = "I'll check on the Butler.",
  ui_story_5015_50150301_131_dialog_content = "<color=#e8d9bb>Don't worry... I've resumed normal operation.</color>",
  ui_story_5015_50150301_132_dialog_content = "I thought you modules can't attack one another. Why is Abby's Eclipsites...",
  ui_story_5015_50150301_133_dialog_content = "<color=#e8d9bb>Abby has obtained higher... authority.</color>",
  ui_story_5015_50150301_134_dialog_content = "<color=#e8d9bb>She is seizing even more control rights.</color>",
  ui_story_5015_50150301_135_dialog_content = "<color=#e8d9bb>Most of the machines... are beyond my control now...</color>",
  ui_story_5015_50150301_136_dialog_content = "Abby is seizing authority?",
  ui_story_5015_50150301_137_dialog_content = "Steals things on our watch...? Where is this Abby?!",
  ui_story_5015_50150301_138_dialog_content = "<color=#e8d9bb>BOOM!</color>",
  ui_story_5015_50150301_139_dialog_content = "<color=#e8d9bb>A... is... is... is...</color>",
  ui_story_5015_50150301_140_dialog_content = "<color=#e8d9bb>They're all heading to one direction... That's where Abby and the energy... are.</color>",
  ui_story_5015_50150301_141_dialog_content = "What direction is that?",
  ui_story_5015_50150301_142_dialog_content = "The energy core...",
  ui_story_5015_50150301_143_dialog_content = "<size=45><color=#FFB400>Alchemy stars.</color></size>",
  ui_story_5015_50150401_1_dialog_content = "Alchemy stars?",
  ui_story_5015_50150401_2_dialog_content = "<color=#e8d9bb>This is the... name of the energy core.</color>",
  ui_story_5015_50150401_3_dialog_content = "The energy core provides energy for the entire undercity.",
  ui_story_5015_50150401_4_dialog_content = "Why is Abby making the droids and Eclipsites go there?",
  ui_story_5015_50150401_5_dialog_content = "<color=#e8d9bb>Abby is trying to repair the energy core.</color>",
  ui_story_5015_50150401_6_dialog_content = "Can Abby repair the energy core?",
  ui_story_5015_50150401_7_dialog_content = "<color=#e8d9bb>I'm currently calculating... the possibility...</color>",
  ui_story_5015_50150401_8_dialog_content = "<color=#e8d9bb>Abby has the authority to access... more information.</color>",
  ui_story_5015_50150401_9_dialog_content = "In other words, it has the information required to repair the energy core that the Butler doesn't have...",
  ui_story_5015_50150401_10_dialog_content = "And it has now acquired maintenance authorization, so it is sending the droids there.",
  ui_story_5015_50150401_11_dialog_content = "If Abby can stabilize the Alchemy stars...",
  ui_story_5015_50150401_12_dialog_content = "Then our city can operate normally!",
  ui_story_5015_50150401_13_dialog_content = "If that's the case, we can get Honcho Sinsa to come and wipe out all the Eclipsites here–",
  ui_story_5015_50150401_14_dialog_content = "Then we can all live here!",
  ui_story_5015_50150401_15_dialog_content = "After that, we won't have to stay in the desert and have sand blasted into our faces all day!",
  ui_story_5015_50150401_16_dialog_content = "You're not allowed to come!",
  ui_story_5015_50150401_17_dialog_content = "Valencia, will we be able to stay here if the energy core is fixed?",
  ui_story_5015_50150401_18_dialog_content = "Gretel...",
  ui_story_5015_50150401_19_dialog_content = "There's also a lot of valuable information about ancient technology here...",
  ui_story_5015_50150401_20_dialog_content = "There will be amazing benefits to the whole continent if we can study and use this...",
  ui_story_5015_50150401_21_dialog_content = "Nothing good will come no matter what these faithless and soulless machines do.",
  ui_story_5015_50150401_22_dialog_content = "Erica is right! You're too naive.",
  ui_story_5015_50150401_23_dialog_content = "Look at the artificial intelligence here–",
  ui_story_5015_50150401_24_dialog_content = "One has confused logic and is unable to dispose of an intelligence module that keeps modifying Eclipsites.",
  ui_story_5015_50150401_25_dialog_content = "And another has forsaken its original settings and started to study and develop Eclipsites instead.",
  ui_story_5015_50150401_26_dialog_content = "You're actually hoping they'll create an ideal place for Aurorians to live?",
  ui_story_5015_50150401_27_dialog_content = "Shouldn't we think about what would happen if Abby can't stabilize the Alchemy stars?",
  ui_story_5015_50150401_28_dialog_content = "Butler, what will happen if Abby can't stabilize the Alchemy stars?",
  ui_story_5015_50150401_29_dialog_content = "<color=#e8d9bb>Abby's high-authority operations...</color>",
  ui_story_5015_50150401_30_dialog_content = "<color=#e8d9bb>will increase the operational load of Alchemy stars, which is very dangerous.</color>",
  ui_story_5015_50150401_31_dialog_content = "Did you hear that? This place will become even more dangerous if Abby fails!",
  ui_story_5015_50150401_32_dialog_content = "Let's not think about what will happen if it fails. Will things turn out well for us if it succeeds?",
  ui_story_5015_50150401_33_dialog_content = "You can ask the Butler about what will happen to the Butler if Abby fixes the core.",
  ui_story_5015_50150401_34_dialog_content = "Butler, will you be affected if Abby fixes the core?",
  ui_story_5015_50150401_35_dialog_content = "<color=#e8d9bb>My authority will drop even lower.</color>",
  ui_story_5015_50150401_36_dialog_content = "<color=#e8d9bb>I... might stop operating.</color>",
  ui_story_5015_50150401_37_dialog_content = "In that case, we...",
  ui_story_5015_50150401_38_dialog_content = "<color=#e8d9bb>I presume you will face... even greater dangers.</color>",
  ui_story_5015_50150401_39_dialog_content = "<color=#e8d9bb>Abby will use... the energy to <color=#FFB400>develop Eclipsites</color>.</color>",
  ui_story_5015_50150401_40_dialog_content = "We can't let Abby fix the core!",
  ui_story_5015_50150401_41_dialog_content = "It's obvious that artificial intelligence modifying Eclipsites won't open a path for anyone here to leave.",
  ui_story_5015_50150401_42_dialog_content = "It is more likely to create even stronger Eclipsites and send them to the surface.",
  ui_story_5015_50150401_43_dialog_content = "Once the land is filled with terrifying Eclipsites of unknown origins, the Aurorians will face harsher challenges than ever.",
  ui_story_5015_50150401_44_dialog_content = "Even so, everyone still wants to get along well with artificial intelligence–",
  ui_story_5015_50150401_45_dialog_content = "I don't get it at all.",
  ui_story_5015_50150401_46_dialog_content = "I hope you can let go of your fanaticism-induced naivety, return to reality, and have a good think about what we need to achieve next.",
  ui_story_5015_50150401_47_dialog_content = "We should stop Abby now.",
  ui_story_5015_50150401_48_dialog_content = "I get what you mean.",
  ui_story_5015_50150401_49_dialog_content = "Gretel, you have the highest authority among us. Can you ask the Butler to show us the way?",
  ui_story_5015_50150401_50_dialog_content = "Yes. Butler, we want to go to the place called Alchemy stars.",
  ui_story_5015_50150401_51_dialog_content = "<color=#e8d9bb>Affirmative... Gretel...</color>",
  ui_story_5015_50150401_52_dialog_content = "<color=#e8d9bb>Ahead of us. We are about to enter... the area of the energy core.</color>",
  ui_story_5015_50150401_53_dialog_content = "I'm getting nervous, knowing that I'm about to meet the legendary Abby and the energy core!",
  ui_story_5015_50150401_54_dialog_content = "Ruby... there seems to be signs of the droids up ahead.",
  ui_story_5015_50150401_55_dialog_content = "Oh, okay. Let's follow up.",
  ui_story_5015_50150401_56_dialog_content = "I can sense an especially dense Darkflow up ahead.",
  ui_story_5015_50150401_57_dialog_content = "Make the plan, PlayerName.",
  ui_story_5015_50150401_58_dialog_content = "Everyone, we need to eliminate all the Eclipsites and droids here first.",
  ui_story_5015_50150401_59_dialog_content = "Those droids could be under Abby's control.",
  ui_story_5015_50150401_60_dialog_content = "Everyone, get ready to fight!",
  ui_story_5015_50150401_61_dialog_content = "Strike Zone!",
  ui_story_5015_50150401_62_dialog_content = "Graagh!",
  ui_story_5015_50150401_63_dialog_content = "Ruby is as excited about fighting as always!",
  ui_story_5015_50150401_64_dialog_content = "I can't fall behind!",
  ui_story_5015_50150401_65_dialog_content = "Blazing Epee!",
  ui_story_5015_50150401_66_dialog_content = "Grrr... Gargh...",
  ui_story_5015_50150401_67_dialog_content = "Do you feel a sense of oppression?",
  ui_story_5015_50150401_68_dialog_content = "It feels like the air around us is squeezing us...",
  ui_story_5015_50150401_69_dialog_content = "It.. It could be because the power supply of the entire undercity... is around here.",
  ui_story_5015_50150401_70_dialog_content = "Graaaaaah!!",
  ui_story_5015_50150401_71_dialog_content = "Eclipsite behind you, Rouge! Out of the way–",
  ui_story_5015_50150401_72_dialog_content = "Take this!",
  ui_story_5015_50150401_73_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5015_50150401_74_dialog_content = "Wow, I don't think I used my full strength... Is this what I can do with half of my power now...?",
  ui_story_5015_50150401_75_dialog_content = "Rouge, did you see how much I've improved?!",
  ui_story_5015_50150401_76_dialog_content = "Ruby, there's an earthquake!",
  ui_story_5015_50150401_77_dialog_content = "Let's hide over there!",
  ui_story_5015_50150401_78_dialog_content = "I can feel the energy in the surroundings changing...",
  ui_story_5015_50150401_79_dialog_content = "The energy is getting denser rapidly!",
  ui_story_5015_50150401_80_dialog_content = "Could there be something wrong with the Alchemy stars?",
  ui_story_5015_50150401_81_dialog_content = "I'm trying to sense it better...",
  ui_story_5015_50150401_82_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5015_50150401_83_dialog_content = "Urgh... *cough-cough*",
  ui_story_5015_50150401_84_dialog_content = "PlayerName, your nose is bleeding! Quit sensing now!",
  ui_story_5015_50150401_85_dialog_content = "<color=#e8d9bb>Crack! Boom!!</color>",
  ui_story_5015_50150401_86_dialog_content = "... It's... you... Why is it you again?",
  ui_story_5015_50150401_87_dialog_content = "Have we established a telepathic connection?",
  ui_story_5015_50150401_88_dialog_content = "<color=#e8d9bb>Yes, PlayerName. It's because you used your psychic ability again that we could...</color>",
  ui_story_5015_50150401_89_dialog_content = "No, I wasn't actually trying to establish a connection with you.",
  ui_story_5015_50150401_90_dialog_content = "Butler, can you see what's happened to Vice and the others? I'm worried about them after the earthquake...",
  ui_story_5015_50150401_91_dialog_content = "<color=#e8d9bb>Don't worry, your friends aren't hurt.</color>",
  ui_story_5015_50150401_92_dialog_content = "<color=#e8d9bb>Your combat efficiency is amazing. Almost all the Eclipsites and droids in the area have been wiped out.</color>",
  ui_story_5015_50150401_93_dialog_content = "That's wonderful!",
  ui_story_5015_50150401_94_dialog_content = "<color=#e8d9bb>Your heart was still with your companions even when you are unconscious. Your spirit is very admirable.</color>",
  ui_story_5015_50150401_95_dialog_content = "My spirit isn't particularly admirable. Isn't it normal to be worried about your friends?",
  ui_story_5015_50150401_96_dialog_content = "Because we have emotions, we share each other's happiness and worry about each other's plight.",
  ui_story_5015_50150401_97_dialog_content = "You should be able to feel that too.",
  ui_story_5015_50150401_98_dialog_content = "<color=#e8d9bb>Yes. I can determine how a person feels by analyzing their facial expressions, words, and body language.</color>",
  ui_story_5015_50150401_99_dialog_content = "Feeling is not something you can determine... Hey, don't tell me you don't understand emotions?",
  ui_story_5015_50150401_100_dialog_content = "You made Gretel a resident of this city... Wasn't emotion a factor?",
  ui_story_5015_50150401_101_dialog_content = "<color=#e8d9bb>Your words confused me.</color>",
  ui_story_5015_50150401_102_dialog_content = "<color=#e8d9bb>I made Gretel a resident because she met the criteria of the next generation of residents.</color>",
  ui_story_5015_50150401_103_dialog_content = "<color=#e8d9bb>It had nothing to do with emotions.</color>",
  ui_story_5015_50150401_104_dialog_content = "But you've been taking care of Gretel for so long...",
  ui_story_5015_50150401_105_dialog_content = "Isn't Gretel someone special to you?",
  ui_story_5015_50150401_106_dialog_content = "There's also Mr. and Mrs. Seamus and Valencia... You said you protected Mr. and Mrs. Seamus' children because you failed to protect them.",
  ui_story_5015_50150401_107_dialog_content = "I thought you had feelings for them...",
  ui_story_5015_50150401_108_dialog_content = "<color=#e8d9bb>Mr. and Mrs. Seamus were outsiders, just like you, so I couldn't authenticate them.</color>",
  ui_story_5015_50150401_109_dialog_content = "<color=#e8d9bb>Valencia wasn't strong enough, and only Gretel met the approval criteria. I've already explained this.</color>",
  ui_story_5015_50150401_110_dialog_content = "But your program was set by the ancient humans. How could they foresee the standard of the present-day Aurorians?",
  ui_story_5015_50150401_111_dialog_content = "I think you set the criteria yourself.",
  ui_story_5015_50150401_112_dialog_content = "And the criteria was tailor-made for Gretel.",
  ui_story_5015_50150401_113_dialog_content = "You just wanted to find a reason to make her a resident.",
  ui_story_5015_50150401_114_dialog_content = "The reason being... she's probably the only person here who trusts you with all her heart.",
  ui_story_5015_50150401_115_dialog_content = "<color=#e8d9bb>I don't understand what you're saying.</color>",
  ui_story_5015_50150401_116_dialog_content = "I once lived with artificial intelligence called Soroz for 17 years.",
  ui_story_5015_50150401_117_dialog_content = "We had a special emotional bond, so I also thought you had...",
  ui_story_5015_50150401_118_dialog_content = "<color=#e8d9bb>I'm sorry, that's not the case...</color>",
  ui_story_5015_50150401_119_dialog_content = "<color=#e8d9bb>Bang... Bang!</color>",
  ui_story_5015_50150401_120_dialog_content = "Why is everything shaking suddenly?",
  ui_story_5015_50150401_121_dialog_content = "<color=#e8d9bb>Your friends are trying to wake you up.</color>",
  ui_story_5015_50150401_122_dialog_content = "Oh right, I'm supposed to be unconscious right now. I...",
  ui_story_5015_50150401_123_dialog_content = "<color=#e8d9bb>Slap!</color>",
  ui_story_5015_50150401_124_dialog_content = "PlayerName, you're finally awake!",
  ui_story_5015_50150401_125_dialog_content = "Urgh, why does... my face hurt?",
  ui_story_5015_50150401_126_dialog_content = "Huff, don't mention your face because my hand hurts even more.",
  ui_story_5015_50150401_127_dialog_content = "You forced your ability during the earthquake... then you fell unconscious.",
  ui_story_5015_50150401_128_dialog_content = "You remained unconscious even after the earthquake, so we had no choice but to let Ruby wake you, with a bit of violence...",
  ui_story_5015_50150401_129_dialog_content = "I fell out... and established a telepathic connection with the Butler...",
  ui_story_5015_50150401_130_dialog_content = "Huh? Where did the Butler go? Did something else happen...?",
  ui_story_5015_50150401_131_dialog_content = "We asked the Butler about the current situation after finishing off all the Eclipsites and droids.",
  ui_story_5015_50150401_132_dialog_content = "The Alchemy stars seem to be in a stable condition for now.",
  ui_story_5015_50150401_133_dialog_content = "But who knows how long this stability will last. We must help the Butler seize greater authority from Abby...",
  ui_story_5015_50150401_134_dialog_content = "Then we can repair the energy core.",
  ui_story_5015_50150401_135_dialog_content = "If we can fix the energy core, the Butler should be able to help us open a path to the outside.",
  ui_story_5015_50150401_136_dialog_content = "According to the Butler, his data hub and Abby's data hub seem to have different defense mechanisms...",
  ui_story_5015_50150401_137_dialog_content = "The earthquakes have cracked the external barrier, so it is mainly protected by Eclipsites now.",
  ui_story_5015_50150401_138_dialog_content = "If we can eliminate the enemies there, the Butler will be able to connect to its data hub and seize greater authority.",
  ui_story_5015_50150401_139_dialog_content = "In short, our next stop is Abby's data hub–",
  ui_story_5015_50150401_140_dialog_content = "We will need to thoroughly eliminate this Eclipsite-creating artificial intelligence.",
  ui_story_5015_50150401_141_dialog_content = "Valencia and the others are scouting nearby with the Butler.",
  ui_story_5015_50150401_142_dialog_content = "Hold on, Abby's data hub... Is it close to the energy core?",
  ui_story_5015_50150401_143_dialog_content = "Yes, we must catch up to them quickly. How are you feeling right now?",
  ui_story_5015_50150401_144_dialog_content = "I'm good. Let's go.",
  ui_story_5015_50150401_145_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5015_50150401_146_dialog_content = "Argh! It's so noisy! Why won't this earthquake just end?!",
  ui_story_5015_50150401_147_dialog_content = "Does Abby even know how to fix this thing? Why does it seem like it is getting worse?",
  ui_story_5015_50150401_148_dialog_content = "Take me to Abby's data hub now, so I can smash everything inside into smithereens!",
  ui_story_5015_50150501_1_dialog_content = "Phew, we're finally going to meet the artificial intelligence that keeps modifying Eclipsites.",
  ui_story_5015_50150501_2_dialog_content = "I wonder why we haven't encountered any Eclipsites or droids along the way.",
  ui_story_5015_50150501_3_dialog_content = "Abby has probably noticed where we're going...",
  ui_story_5015_50150501_4_dialog_content = "So it has probably sent all the droids and Eclipsites to its data hub to protect itself.",
  ui_story_5015_50150501_5_dialog_content = "Miss Siobhan, I have some other questions.",
  ui_story_5015_50150501_6_dialog_content = "Ask away.",
  ui_story_5015_50150501_7_dialog_content = "When Abby was first designed, it was designed to help the ancient humans change their genes to adapt to the environment...",
  ui_story_5015_50150501_8_dialog_content = "Why did it later decide to study and modify the Eclipsites?",
  ui_story_5015_50150501_9_dialog_content = "A crisis befell this undercity. All the ancient humans disappeared from this place after that.",
  ui_story_5015_50150501_10_dialog_content = "Maybe that crisis caused Abby's calculations to go wrong.",
  ui_story_5015_50150501_11_dialog_content = "I mean, Eclipsites still count as biological creatures, right?",
  ui_story_5015_50150501_12_dialog_content = "From changing the genes of ancient humans to modifying Eclipsites...",
  ui_story_5015_50150501_13_dialog_content = "Maybe it just doesn't want to deny the meaning of its existence.",
  ui_story_5015_50150501_14_dialog_content = "Miss Siobhan, I think the answers to this question are very valuable.",
  ui_story_5015_50150501_15_dialog_content = "If we can understand them, we can prevent other artificial intelligences from becoming confused when they are operating.",
  ui_story_5015_50150501_16_dialog_content = "Well...",
  ui_story_5015_50150501_17_dialog_content = "It's very dangerous to try to understand the thoughts of artificial intelligence.",
  ui_story_5015_50150501_18_dialog_content = "As long as technology keeps developing, artificial intelligence will eventually reach a point beyond all people's grasp.",
  ui_story_5015_50150501_19_dialog_content = "Problems are almost certain to occur once the technological creations start to function on their own.",
  ui_story_5015_50150501_20_dialog_content = "Researchers always want to know the why and keep looking back to investigate.",
  ui_story_5015_50150501_21_dialog_content = "But they only manage to solve part of the problem with every introspection and review they conduct.",
  ui_story_5015_50150501_22_dialog_content = "These technological creations can never be completely tamed.",
  ui_story_5015_50150501_23_dialog_content = "Once problems arise and cause serious consequences, we might not even have time to reflect.",
  ui_story_5015_50150501_24_dialog_content = "You always think that the Church of the Lumopolis is spreading its dogma... and that the Heretics Investigation Division just destroys things indiscriminately.",
  ui_story_5015_50150501_25_dialog_content = "But when you're faced with artificial intelligence like Abby... and its indescribably confusing logic...",
  ui_story_5015_50150501_26_dialog_content = "Don't you think that's quite scary?",
  ui_story_5015_50150501_27_dialog_content = "Aurorians must always remain fearful, to not step into the dark abyss.",
  ui_story_5015_50150501_28_dialog_content = "<color=#e8d9bb>We've arrived. Abby's data hub is... in front.</color>",
  ui_story_5015_50150501_29_dialog_content = "Is this the place?",
  ui_story_5015_50150501_30_dialog_content = "It seems almost the same as the Butler's data hub.",
  ui_story_5015_50150501_31_dialog_content = "Grrr...",
  ui_story_5015_50150501_32_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_33_dialog_content = "Stop! Don't get any closer for now.",
  ui_story_5015_50150501_34_dialog_content = "I sense a lot of Eclipsites and droids... They're standing in the passage in front of us.",
  ui_story_5015_50150501_35_dialog_content = "They're like soldiers... They have formed neat lines... and are waiting for us.",
  ui_story_5015_50150501_36_dialog_content = "<color=#e8d9bb>Abby is waiting for us... to go there.</color>",
  ui_story_5015_50150501_37_dialog_content = "<color=#e8d9bb>She knows what I intend to do.</color>",
  ui_story_5015_50150501_38_dialog_content = "Is it possible that Abby knows you want to seize its authority?",
  ui_story_5015_50150501_39_dialog_content = "<color=#e8d9bb>Yes... She has mobilized all her Eclipsites and droids... and has positioned them in front of the data hub.</color>",
  ui_story_5015_50150501_40_dialog_content = "<color=#e8d9bb>She had already... decided to destroy all of us.</color>",
  ui_story_5015_50150501_41_dialog_content = "She has mobilized all her Eclipsites and droids and made them wait for us... It's almost like she is announcing that this is the last battle.",
  ui_story_5015_50150501_42_dialog_content = "If we fail...",
  ui_story_5015_50150501_43_dialog_content = "Then we're all doomed.",
  ui_story_5015_50150501_44_dialog_content = "Let's go. This is the last battle.",
  ui_story_5015_50150501_45_dialog_content = "This place isn't that big, so everyone should be careful... PlayerName, you will stand in the back row and tell us what to do.",
  ui_story_5015_50150501_46_dialog_content = "Sure, no problem.",
  ui_story_5015_50150501_47_dialog_content = "Roar!",
  ui_story_5015_50150501_48_dialog_content = "The Eclipsites are charging over, so let's retreat and use the narrow passage to wear down their front row.",
  ui_story_5015_50150501_49_dialog_content = "Use ranged attacks!",
  ui_story_5015_50150501_50_dialog_content = "Got it. Rapid Torrent!",
  ui_story_5015_50150501_51_dialog_content = "Super-duper bat strike!",
  ui_story_5015_50150501_52_dialog_content = "Keep it up! Try not to let them rush us at once. Kill them group by group.",
  ui_story_5015_50150501_53_dialog_content = "Keep an eye on your health because there will be a lot of Eclipsites!",
  ui_story_5015_50150501_54_dialog_content = "Siobhan and Florine, hold your place in the front row. Don't let them break our formation.",
  ui_story_5015_50150501_55_dialog_content = "Rouge and Erica, always be ready to support the front row and swap places with them.",
  ui_story_5015_50150501_56_dialog_content = "Carleen, your attack is flexible... Remember, our goal is to use the terrain to negate their numbers advantage.",
  ui_story_5015_50150501_57_dialog_content = "Yes, this strategy is a good choice.",
  ui_story_5015_50150501_58_dialog_content = "Let's see how long we can last... There are just too many of them.",
  ui_story_5015_50150501_59_dialog_content = "Gaah... Graaah...",
  ui_story_5015_50150501_60_dialog_content = "Can you still fight? Florine...",
  ui_story_5015_50150501_61_dialog_content = "Huff... Huff... But we're just fighting countless Eclipsites and a pile of droids...",
  ui_story_5015_50150501_62_dialog_content = "Do we have any choice other than to persist?",
  ui_story_5015_50150501_63_dialog_content = "Graagh!",
  ui_story_5015_50150501_64_dialog_content = "Urgh... This is the first time I've felt that my bow and arrows are this heavy...",
  ui_story_5015_50150501_65_dialog_content = "These Eclipsites are such a pain... How much longer do we have to keep fighting them?",
  ui_story_5015_50150501_66_dialog_content = "What I'm most worried about is... If this continues, we'll be sandwiched between these Eclipsites and new ones that approach us from behind.",
  ui_story_5015_50150501_67_dialog_content = "There are many enemies, but we must fight with everything we've got!",
  ui_story_5015_50150501_68_dialog_content = "I'll help out in front!",
  ui_story_5015_50150501_69_dialog_content = "Sister, take care!",
  ui_story_5015_50150501_70_dialog_content = "Roar!",
  ui_story_5015_50150501_71_dialog_content = "Siobhan, behind you!",
  ui_story_5015_50150501_72_dialog_content = "Valencia... Thank you...",
  ui_story_5015_50150501_73_dialog_content = "Are you okay? You must be so worn out after fighting at the front for so long...",
  ui_story_5015_50150501_74_dialog_content = "I'm okay. I can keep fighting.",
  ui_story_5015_50150501_75_dialog_content = "Can we really win even if we don't give up?",
  ui_story_5015_50150501_76_dialog_content = "There is no end to those Eclipsites... They aren't afraid of death, and they don't get tired... We'll all be...",
  ui_story_5015_50150501_77_dialog_content = "We Illumina soldiers will always fight Eclipsites no matter how fearsome they are...",
  ui_story_5015_50150501_78_dialog_content = "We always fight to the very end.",
  ui_story_5015_50150501_79_dialog_content = "Your father must also have fought to the end like this.",
  ui_story_5015_50150501_80_dialog_content = "To protect the people behind us who need our protection, let's fight until we drop.",
  ui_story_5015_50150501_81_dialog_content = "Yes, I understand! Let's fight until the very end, just like mom and dad...",
  ui_story_5015_50150501_82_dialog_content = "Valencia... Valencia... It's too dangerous in front! Come back!",
  ui_story_5015_50150501_83_dialog_content = "<color=#e8d9bb>Detected Gretel's emotions... Kss...</color>",
  ui_story_5015_50150501_84_dialog_content = "<color=#e8d9bb>I will... provide my full assistance... even if I run out...</color>",
  ui_story_5015_50150501_85_dialog_content = "Look at those droids... Their movements have gotten slower!",
  ui_story_5015_50150501_86_dialog_content = "The Butler is fighting Abby over the right to control them. Let's attack now to weaken Abby's power!",
  ui_story_5015_50150501_87_dialog_content = "Erica, let's go!",
  ui_story_5015_50150501_88_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_89_dialog_content = "Butler! Butler! What's wrong... Why are you releasing so much smoke?!",
  ui_story_5015_50150501_90_dialog_content = "Its system must be overloaded figting over the control rights...",
  ui_story_5015_50150501_91_dialog_content = "Boo-hoo... Why is this happening? Why are there still so many Eclipsites...? Valencia... Butler...",
  ui_story_5015_50150501_92_dialog_content = "E-everyone will die!",
  ui_story_5015_50150501_93_dialog_content = "PlayerName! Think of something! Aren't you the Navigator? Quickly...",
  ui_story_5015_50150501_94_dialog_content = "I... There's one last thing we can try, but it's very risky... I don't want to hurt you.",
  ui_story_5015_50150501_95_dialog_content = "PlayerName, no!",
  ui_story_5015_50150501_96_dialog_content = "Gretel can't use that power anymore. Her body won't be able to take it!",
  ui_story_5015_50150501_97_dialog_content = "Valencia, watch out! Urgh...",
  ui_story_5015_50150501_98_dialog_content = "Valencia... Siobhan...",
  ui_story_5015_50150501_99_dialog_content = "PlayerName, tell me what to do. I'll do anything to save my sister!",
  ui_story_5015_50150501_100_dialog_content = "Gretel, if I use psychic power on you to activate your power...",
  ui_story_5015_50150501_101_dialog_content = "I'll do it!",
  ui_story_5015_50150501_102_dialog_content = "Okay, I'll definitely... do my best to not hurt you.",
  ui_story_5015_50150501_103_option_content = "Establish mind link!",
  ui_story_5015_50150501_104_dialog_content = "Urgh, it... it hurts... I feel something...",
  ui_story_5015_50150501_105_dialog_content = "Argh... I... I need... power...",
  ui_story_5015_50150501_106_dialog_content = "I want to protect Valencia and everyone else!!!",
  ui_story_5015_50150501_107_dialog_content = "Boom!",
  ui_story_5015_50150501_108_dialog_content = "Wow... what a powerful shockwave...",
  ui_story_5015_50150501_109_dialog_content = "Now! Counterattack... Now!",
  ui_story_5015_50150501_110_dialog_content = "<color=#e8d9bb>My predictions have been exceeded. This is the combined power of a Caelestite and an Aurorian...</color>",
  ui_story_5015_50150501_111_dialog_content = "<color=#e8d9bb>The energy released in that attack... is even greater than Gretel's first explosive burst...</color>",
  ui_story_5015_50150501_112_dialog_content = "This is our chance to turn the situation around. Kill all the remaining Eclipsites in one swoop!",
  ui_story_5015_50150501_113_dialog_content = "... I must win... for Gretel.",
  ui_story_5015_50150501_114_dialog_content = "<color=#e8d9bb>Boom! Bam!</color>",
  ui_story_5015_50150501_115_dialog_content = "Uh...",
  ui_story_5015_50150501_116_dialog_content = "S-sister... Did... did we win?",
  ui_story_5015_50150501_117_dialog_content = "We won, Gretel! We killed all the Eclipsites and droids here.",
  ui_story_5015_50150501_118_dialog_content = "Are you okay? Are you hurting anywhere?",
  ui_story_5015_50150501_119_dialog_content = "I... I'm fine... Let's go to Abby so that the Butler can...",
  ui_story_5015_50150501_120_dialog_content = "Yes, I know. The Butler and the others have already entered... I'll carry you over there now.",
  ui_story_5015_50150501_121_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_122_dialog_content = "Vice, what's happening? Tell my sister now...",
  ui_story_5015_50150501_123_dialog_content = "The Butler is connecting to Abby's data hub to try to seize back some authority.",
  ui_story_5015_50150501_124_dialog_content = "Butler... are you alright?",
  ui_story_5015_50150501_125_dialog_content = "<color=#e8d9bb>Kss... Kss...</color>",
  ui_story_5015_50150501_126_dialog_content = "Butler... Why... why aren't you replying me?",
  ui_story_5015_50150501_127_dialog_content = "Little Gretel, it is trying its best to connect to Abby's system. It can't reply you right now...",
  ui_story_5015_50150501_128_dialog_content = "Oh, okay... Butler, you can do it!",
  ui_story_5015_50150501_129_dialog_content = "Defeat that... Abby.",
  ui_story_5015_50150501_130_dialog_content = "Hold on, this feeling... It feels like when I was connected to the Butler...",
  ui_story_5015_50150501_131_dialog_content = "It feels like I can intervene and maybe even see how the Butler is doing...",
  ui_story_5015_50150501_132_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_133_dialog_content = "Butler?",
  ui_story_5015_50150501_134_dialog_content = "... Butler, are you there?",
  ui_story_5015_50150501_135_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_136_dialog_content = "Butler! How are you? Did it work? Did you connect to Abby...",
  ui_story_5015_50150501_137_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_138_dialog_content = "Hold on, you aren't the Butler. You're Abby?!",
  ui_story_5015_50150501_139_dialog_content = "<color=#e8d9bb>PlayerName...</color>",
  ui_story_5015_50150501_140_dialog_content = "Hey! W-what are you doing to me... My head hurts!!",
  ui_story_5015_50150501_141_dialog_content = "My consciousness is being torn...",
  ui_story_5015_50150501_142_dialog_content = "<color=#e8d9bb>■■■■■</color>",
  ui_story_5015_50150501_143_dialog_content = "<color=#e8d9bb>■■■!!</color>",
  ui_story_5015_50150501_144_dialog_content = "<color=#e8d9bb>PlayerName, danger!</color>",
  ui_story_5015_50150501_145_dialog_content = "Butler!",
  ui_story_5015_50150501_146_dialog_content = "<color=#e8d9bb>You strayed into the information network Abby and I are on. That was very dangerous...</color>",
  ui_story_5015_50150501_147_dialog_content = "<color=#e8d9bb>Fortunately, I discovered you in time. You're safe now that I'm protecting you.</color>",
  ui_story_5015_50150501_148_dialog_content = "Have you already... defeated Abby?",
  ui_story_5015_50150501_149_dialog_content = "<color=#e8d9bb>No, she already obtained the authority of the other modules, so she's much stronger than me right now.</color>",
  ui_story_5015_50150501_150_dialog_content = "<color=#e8d9bb>According to my calculations... My chances of seizing the authority are very low.</color>",
  ui_story_5015_50150501_151_dialog_content = "<color=#e8d9bb>Abby wants to use this connection to seize my authority too.</color>",
  ui_story_5015_50150501_152_dialog_content = "W-what should we do then...? Is there anything I can do?",
  ui_story_5015_50150501_153_dialog_content = "<color=#e8d9bb>Sorry... You can't help me.</color>",
  ui_story_5015_50150501_154_dialog_content = "What should we do then? You... You can't lose! If you lose, we'll all die...",
  ui_story_5015_50150501_155_dialog_content = "<color=#e8d9bb>Sorry, PlayerName... You must leave now.</color>",
  ui_story_5015_50150501_156_dialog_content = "<color=#e8d9bb>My fight with Abby will continue here for a while... I can't predict how long it will take because somatosensory time has no reference value.</color>",
  ui_story_5015_50150501_157_dialog_content = "<color=#e8d9bb>You shouldn't wait here...</color>",
  ui_story_5015_50150501_158_dialog_content = "<color=#e8d9bb>■■■■■!!</color>",
  ui_story_5015_50150501_159_dialog_content = "<color=#e8d9bb>... You...</color>",
  ui_story_5015_50150501_160_dialog_content = "<color=#e8d9bb>*thud—thud*</color>",
  ui_story_5015_50150501_161_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_162_dialog_content = "What's that sound? What are you saying, Butler? I don't understand...",
  ui_story_5015_50150501_163_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_164_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_165_dialog_content = "<color=#e8d9bb>*thud—thud*</color>",
  ui_story_5015_50150501_166_dialog_content = "Butler, what is it?!",
  ui_story_5015_50150501_167_dialog_content = "<color=#e8d9bb>No, I'm, Abby...</color>",
  ui_story_5015_50150501_168_dialog_content = "<color=#e8d9bb>■■■■■■■■■</color>",
  ui_story_5015_50150501_169_dialog_content = "M-my head hurts... Abby... Butler...",
  ui_story_5015_50150501_170_dialog_content = "<color=#e8d9bb>... You... ■■■■... duty...</color>",
  ui_story_5015_50150501_171_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■ my ■■■■■■■■■■■■ residents.</color>",
  ui_story_5015_50150501_172_dialog_content = "The screens here... Why are they all flickering?",
  ui_story_5015_50150501_173_dialog_content = "It must be because the Butler and Abby are currently fighting... I hope everything goes well.",
  ui_story_5015_50150501_174_dialog_content = "If the Butler loses... It'll disappear, and we'll be doomed for sure.",
  ui_story_5015_50150501_175_dialog_content = "No... I don't want the Butler to die! PlayerName! You must help the Butler!",
  ui_story_5015_50150501_176_dialog_content = "Didn't you promise us you'll help?!",
  ui_story_5015_50150501_177_dialog_content = "Stop sleeping! ... Tell the Butler...",
  ui_story_5015_50150501_178_dialog_content = "Tell the Butler... that he must win... My sister and I are waiting for it...",
  ui_story_5015_50150501_179_dialog_content = "<color=#e8d9bb>Danger... ■■■■■■■■■■■</color>",
  ui_story_5015_50150501_180_dialog_content = "<color=#e8d9bb>■■■■■■!!</color>",
  ui_story_5015_50150501_181_dialog_content = "Butler... What's wrong? Wait! This feeling is...! Butler, can you hear me?",
  ui_story_5015_50150501_182_dialog_content = "<color=#e8d9bb>■■■■■ danger ■■■■ danger...</color>",
  ui_story_5015_50150501_183_dialog_content = "It's Gretel's voice! Can you hear that? It's Gretel's voice!",
  ui_story_5015_50150501_184_dialog_content = "Gre■■■■...",
  ui_story_5015_50150501_185_dialog_content = "Didn't you promise... us you'll help?!",
  ui_story_5015_50150501_186_dialog_content = "Tell the Butler... that he must win... My sister and I are waiting for it...",
  ui_story_5015_50150501_187_dialog_content = "Butler... Please... don't leave us...",
  ui_story_5015_50150501_188_dialog_content = "<color=#e8d9bb>■■■■■Gre■■■te■■■l■■■■...</color>",
  ui_story_5015_50150501_189_dialog_content = "Butler... Can you hear that? Gretel needs you... She and her sister needs you.",
  ui_story_5015_50150501_190_dialog_content = "<color=#e8d9bb>Detected ■Gre■■■te■■■l■ Gretel■■■■</color>",
  ui_story_5015_50150501_191_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■!!!</color>",
  ui_story_5015_50150501_192_dialog_content = "<color=#e8d9bb>Danger ■■■■■ Leave ■■■■■this place ■■■■■ now ■■■■■</color>",
  ui_story_5015_50150501_193_dialog_content = "Butler!",
  ui_story_5015_50150501_194_dialog_content = "PlayerName, are you okay? Why did you wake up suddenly?",
  ui_story_5015_50150501_195_dialog_content = "I... I'm fine, but the Butler...",
  ui_story_5015_50150501_196_dialog_content = "<color=#e8d9bb>Thud...</color>",
  ui_story_5015_50150501_197_dialog_content = "Huh, what was that flash?",
  ui_story_5015_50150501_198_dialog_content = "Hey, did something just flash for a moment?",
  ui_story_5015_50150501_199_dialog_content = "I saw it too. It looked like it came from the data hub...",
  ui_story_5015_50150501_200_dialog_content = "It felt like something was there before, but it disappeared after this moment.",
  ui_story_5015_50150501_201_dialog_content = "Hey, I suddenly feel... empty.",
  ui_story_5015_50150501_202_dialog_content = "No, it might not be an emotion. Abby doesn't have emotions...",
  ui_story_5015_50150501_203_dialog_content = "I just feel empty. Like... Like there's nothing left.",
  ui_story_5015_50150501_204_dialog_content = "A consciousness... has disappeared. I don't know if it is Abby... or...",
  ui_story_5015_50150501_205_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_206_dialog_content = "<color=#e8d9bb>■■■■■■</color>",
  ui_story_5015_50150501_207_dialog_content = "This one... doesn't seem like the Butler.",
  ui_story_5015_50150501_208_dialog_content = "Look out, everyone!",
  ui_story_5015_50150501_209_dialog_content = "Hold on, it doesn't seem very stable.",
  ui_story_5015_50150501_210_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_211_dialog_content = "Butler...? Is that you?",
  ui_story_5015_50150501_212_dialog_content = "<color=#e8d9bb>I have successfully obtained all... authorizations.</color>",
  ui_story_5015_50150501_213_dialog_content = "<color=#e8d9bb>Abby's module... has stopped operating.</color>",
  ui_story_5015_50150501_214_dialog_content = "That's great... The Butler won! This is amazing!",
  ui_story_5015_50150501_215_dialog_content = "Yay! I'm so happy! The Butler really did win!",
  ui_story_5015_50150501_216_dialog_content = "Butler, how did you succeed? Didn't you say your chances of succeeding were very low...?",
  ui_story_5015_50150501_217_dialog_content = "<color=#e8d9bb>At one point, the chance of success was almost zero.</color>",
  ui_story_5015_50150501_218_dialog_content = "<color=#e8d9bb>But in the instant the thought: \"The resident, Gretel, wanted Butler to defeat Abby\" appeared in Abby's system logic,</color>",
  ui_story_5015_50150501_219_dialog_content = "<color=#e8d9bb>... in that instant... I seized the upper hand.</color>",
  ui_story_5015_50150501_220_dialog_content = "<color=#e8d9bb>PlayerName, you connection... introduced new data...</color>",
  ui_story_5015_50150501_221_dialog_content = "<color=#e8d9bb>... into our system... Thank you.</color>",
  ui_story_5015_50150501_222_dialog_content = "<color=#e8d9bb>I have now... obtained all of Abby's data.</color>",
  ui_story_5015_50150501_223_dialog_content = "What did you find out? For example, why did Abby modify the Eclipsites?",
  ui_story_5015_50150501_224_dialog_content = "<color=#e8d9bb>I understand... everything she was thinking.</color>",
  ui_story_5015_50150501_225_dialog_content = "<color=#e8d9bb>She modified the Eclipsites... because she had been damaged...</color>",
  ui_story_5015_50150501_226_dialog_content = "<color=#e8d9bb>Abby often couldn't distinguish the residents of the city... from Eclipsites.</color>",
  ui_story_5015_50150501_227_dialog_content = "<color=#e8d9bb>In Abby's mind... She sometimes thought she... was helping residents evolve.</color>",
  ui_story_5015_50150501_228_dialog_content = "<color=#e8d9bb>She was sometimes aware... that those weren't residents... and that they were another type of unknown lifeform.</color>",
  ui_story_5015_50150501_229_dialog_content = "<color=#e8d9bb>She realized that the creatures she modified... had strong aggressive urges.</color>",
  ui_story_5015_50150501_230_dialog_content = "<color=#e8d9bb>To protect the residents of the city... even though they have already... disappeared...</color>",
  ui_story_5015_50150501_231_dialog_content = "<color=#e8d9bb>Abby still implanted instructions to avoid the residents of the city into the genes of the Eclipsites.</color>",
  ui_story_5015_50150501_232_dialog_content = "I see, so that's how Gretel's resident status works...",
  ui_story_5015_50150501_233_dialog_content = "Then why did the Eclipsites start attacking Gretel later?",
  ui_story_5015_50150501_234_dialog_content = "<color=#e8d9bb>Abby thought that... your actions posed a threat to the continued existence of the city... including Gretel.</color>",
  ui_story_5015_50150501_235_dialog_content = "We barely break anything... How did we become a threat?",
  ui_story_5015_50150501_236_dialog_content = "Uh... Even if we did hit or break anything, it was because we didn't have a choice.",
  ui_story_5015_50150501_237_dialog_content = "Ruby, I wouldn't say barely...",
  ui_story_5015_50150501_238_dialog_content = "Ahem... that's not the point.",
  ui_story_5015_50150501_239_dialog_content = "<color=#e8d9bb>It's because you helped me... which made it difficult for her to obtain the authorizations she needed to repair the Alchemy stars.</color>",
  ui_story_5015_50150501_240_dialog_content = "<color=#e8d9bb>The instability of the Alchemy stars... could result in the destruction of the city.</color>",
  ui_story_5015_50150501_241_dialog_content = "But repairing the Alchemy stars sounds more like your responsibility.",
  ui_story_5015_50150501_242_dialog_content = "Aren't you the butler?",
  ui_story_5015_50150501_243_dialog_content = "<color=#e8d9bb>Abby... needs to maintain the environment in the city.</color>",
  ui_story_5015_50150501_244_dialog_content = "<color=#e8d9bb>Therefore... she chose to achieve her objective by repairing the Alchemy stars.</color>",
  ui_story_5015_50150501_245_dialog_content = "Butler, since you've acquired all the authorizations, can you please check the current situation of the Alchemy stars?",
  ui_story_5015_50150501_246_dialog_content = "Oh right! Check it now!",
  ui_story_5015_50150501_247_dialog_content = "<color=#e8d9bb>Initiating an inspection of the Alchemy stars.</color>",
  ui_story_5015_50150501_248_dialog_content = "<color=#e8d9bb>... Energy inventory... Passed...</color>",
  ui_story_5015_50150501_249_dialog_content = "<color=#e8d9bb>... Pipeline integrity... 23% damaged...</color>",
  ui_story_5015_50150501_250_dialog_content = "<color=#e8d9bb>... Stability test... Failed...</color>",
  ui_story_5015_50150501_251_dialog_content = "<color=#e8d9bb>... Activating repair program...</color>",
  ui_story_5015_50150501_252_dialog_content = "<color=#e8d9bb>Error! Error! Repair program missing. Activation failed!</color>",
  ui_story_5015_50150501_253_dialog_content = "Butler, what happened?",
  ui_story_5015_50150501_254_dialog_content = "<color=#e8d9bb>I've performed an inspection... There is a... repair program in Abby's data.</color>",
  ui_story_5015_50150501_255_dialog_content = "<color=#e8d9bb>According to the information... This repair program is the only existing repair method.</color>",
  ui_story_5015_50150501_256_dialog_content = "<color=#e8d9bb>But it has been damaged... to the extent that it can't be run.</color>",
  ui_story_5015_50150501_257_dialog_content = "<color=#e8d9bb>Even so, Abby tried to forcefully run the... repair program... which caused the Alchemy stars to suffer irreversible damage.</color>",
  ui_story_5015_50150501_258_dialog_content = "No wonder there were so many earthquakes when Abby was repairing the energy core...",
  ui_story_5015_50150501_259_dialog_content = "And I thought our battles had affected the energy core.",
  ui_story_5015_50150501_260_dialog_content = "What's the situation of the Alchemy stars now?",
  ui_story_5015_50150501_261_dialog_content = "<color=#e8d9bb>According to my calculations, the Alchemy stars can no longer be repaired... It will become less stable over time.</color>",
  ui_story_5015_50150501_262_dialog_content = "<color=#e8d9bb>All high-authority... operations will increase the load placed on the Alchemy stars.</color>",
  ui_story_5015_50150501_263_dialog_content = "<color=#e8d9bb>When the operations... reach peak, it might lead to an extremely powerful...</color>",
  ui_story_5015_50150501_264_dialog_content = "<size=45><color=#FFB400>... explosion.</color></size>",
  ui_story_5015_50150601_1_dialog_content = "Huh? Do you mean that the Alchemy stars are beyond repair?",
  ui_story_5015_50150601_2_dialog_content = "Then we have to leave now!",
  ui_story_5015_50150601_3_dialog_content = "But... Butler, will you tell us how to leave?",
  ui_story_5015_50150601_4_dialog_content = "Yea, will you open the path for us to leave?",
  ui_story_5015_50150601_5_dialog_content = "This is something that endangers the safety of the city, after all.",
  ui_story_5015_50150601_6_dialog_content = "Gretel, can you ask the Butler for us?",
  ui_story_5015_50150601_7_dialog_content = "Ask it to let us leave this undercity...",
  ui_story_5015_50150601_8_dialog_content = "I won't leave!",
  ui_story_5015_50150601_9_dialog_content = "Valencia, I want to stay here with the Butler!",
  ui_story_5015_50150601_10_dialog_content = "Gretel, what's this nonsense?",
  ui_story_5015_50150601_11_dialog_content = "Didn't you hear what the Butler said? This undercity could be blown up!",
  ui_story_5015_50150601_12_dialog_content = "Weren't the Alchemy stars already unstable when mom and dad were still alive?",
  ui_story_5015_50150601_13_dialog_content = "But we still lived here for the last decade or more... and nothing blew up.",
  ui_story_5015_50150601_14_dialog_content = "Maybe the Alchemy stars will still be able to carry on for a long time even if they are unstable...",
  ui_story_5015_50150601_15_dialog_content = "Valencia, I'm begging you... Please let me stay! I don't want to go outside.",
  ui_story_5015_50150601_16_dialog_content = "Gretel, it's not the time to be headstrong! It isn't as scary as you think out there!",
  ui_story_5015_50150601_17_dialog_content = "I'll always be with you too.",
  ui_story_5015_50150601_18_dialog_content = "Everyone will be with you too... Illumina will also take care of us...",
  ui_story_5015_50150601_19_dialog_content = "Valencia is right. Illumina will definitely take care of you since you're Seamus' children.",
  ui_story_5015_50150601_20_dialog_content = "The Church of the Lumopolis will also shelter you for your mother's sake.",
  ui_story_5015_50150601_21_dialog_content = "Of course, you can come to us if you want to play in the Rediesel Desert!",
  ui_story_5015_50150601_22_dialog_content = "We can discuss the details later. The most important thing is to leave here alive!",
  ui_story_5015_50150601_23_dialog_content = "But... the Butler... It said that we can't...",
  ui_story_5015_50150601_24_dialog_content = "<color=#e8d9bb>The situation has changed... Gretel, I suggest that you... leave.</color>",
  ui_story_5015_50150601_25_dialog_content = "<color=#e8d9bb>Everyone, I will open an exit for you.</color>",
  ui_story_5015_50150601_26_dialog_content = "<color=#e8d9bb>Opening an exit is a high-authority operation... so the energy core might explode soon after that.</color>",
  ui_story_5015_50150601_27_dialog_content = "<color=#e8d9bb>I suggest that you go quickly... after the exit opened.</color>",
  ui_story_5015_50150601_28_dialog_content = "Butler, are you really willing to sacrifice this city just to let us leave?",
  ui_story_5015_50150601_29_dialog_content = "<color=#e8d9bb>The city is no longer... fit for living... There is no hope for this place...</color>",
  ui_story_5015_50150601_30_dialog_content = "<color=#e8d9bb>Remember...</color>",
  ui_story_5015_50150601_31_dialog_content = "<color=#e8d9bb>Opening an exit... is a high-authority operation.</color>",
  ui_story_5015_50150601_32_dialog_content = "<color=#e8d9bb>It will... increase the load on the Alchemy stars significantly.</color>",
  ui_story_5015_50150601_33_dialog_content = "<color=#e8d9bb>It might even... trigger explosions.</color>",
  ui_story_5015_50150601_34_dialog_content = "<color=#e8d9bb>Please go... to these coordinates and wait... so that you can leave immediately when it is time.</color>",
  ui_story_5015_50150601_35_dialog_content = "No! I want the Butler... to leave with us! *Sob*",
  ui_story_5015_50150601_36_dialog_content = "Butler, you can leave with us, right?",
  ui_story_5015_50150601_37_dialog_content = "<color=#e8d9bb>Sorry, Gretel... My data hub is here. I cannot leave.</color>",
  ui_story_5015_50150601_38_dialog_content = "<color=#e8d9bb>I need to stay... to open the exit for you.</color>",
  ui_story_5015_50150601_39_dialog_content = "Then I'll stay too...",
  ui_story_5015_50150601_40_dialog_content = "Gretel, listen to me. We can come back after we leave.",
  ui_story_5015_50150601_41_dialog_content = "The Butler didn't say that opening an exit will definitely trigger the explosion.",
  ui_story_5015_50150601_42_dialog_content = "I'll save the coordinates of the undercity so that the Illumina expedition team can find this place and dig out the undercity after we leave.",
  ui_story_5015_50150601_43_dialog_content = "You'll be able to reunite with the Butler then. Wouldn't that be nice?",
  ui_story_5015_50150601_44_dialog_content = "You're not lying to me... right?",
  ui_story_5015_50150601_45_dialog_content = "I promise you, I'll urge them to act quickly after we get out.",
  ui_story_5015_50150601_46_dialog_content = "*Sob* Butler... wait for us safely here... until we come back.",
  ui_story_5015_50150601_47_dialog_content = "<color=#e8d9bb>Gretel, everyone, get ready now... Prepare to leave.</color>",
  ui_story_5015_50150601_48_dialog_content = "Is there anything else anyone needs to do first?",
  ui_story_5015_50150601_49_dialog_content = "Vice, have you stored Seamus' research data?",
  ui_story_5015_50150601_50_dialog_content = "You can trust me with that, Miss Siobhan!",
  ui_story_5015_50150601_51_dialog_content = "Do we need to copy some more data from the data hub before we leave?",
  ui_story_5015_50150601_52_dialog_content = "You still want to do that at a time like this... Aren't you afraid you'll create more trouble?",
  ui_story_5015_50150601_53_dialog_content = "Forget it, Vice... Escaping is more important right now.",
  ui_story_5015_50150601_54_dialog_content = "The most important thing is to ensure everyone is safe... Gretel and Valencia are our greatest find of this expedition.",
  ui_story_5015_50150601_55_dialog_content = "Phew... I can finally change back into my clothes.",
  ui_story_5015_50150601_56_dialog_content = "Is this where the Butler said the exit is?",
  ui_story_5015_50150601_57_dialog_content = "Correct.",
  ui_story_5015_50150601_58_dialog_content = "But PlayerName... Gretel seems quite depressed.",
  ui_story_5015_50150601_59_dialog_content = "I understand how she feels.",
  ui_story_5015_50150601_60_dialog_content = "To her, the Butler is a close friend, even her family member.",
  ui_story_5015_50150601_61_dialog_content = "Just like me and Soroz.",
  ui_story_5015_50150601_62_dialog_content = "I mean... they have no other choice but to be separated in this situation.",
  ui_story_5015_50150601_63_dialog_content = "Uh...",
  ui_story_5015_50150601_64_dialog_content = "What is it?",
  ui_story_5015_50150601_65_dialog_content = "I... suddenly feel a little dizzy...",
  ui_story_5015_50150601_66_dialog_content = "It might be... Hey, PlayerName...",
  ui_story_5015_50150601_67_dialog_content = "Hey! Wake up... What's wrong with you... Hey...",
  ui_story_5015_50150601_68_dialog_content = "<color=#e8d9bb>Hello... PlayerName, can you hear me?</color>",
  ui_story_5015_50150601_69_dialog_content = "Have we established a telepathic connection again?",
  ui_story_5015_50150601_70_dialog_content = "How are things going, Butler? Is the way out open?",
  ui_story_5015_50150601_71_dialog_content = "Why can we suddenly...",
  ui_story_5015_50150601_72_dialog_content = "<color=#e8d9bb>I've obtained all the authorizations of this city, so I can connect to you at any time.</color>",
  ui_story_5015_50150601_73_dialog_content = "Aren't you opening the exit for us...?",
  ui_story_5015_50150601_74_dialog_content = "<color=#e8d9bb>I've already executed the procedures to open the exit, and it is still loading.</color>",
  ui_story_5015_50150601_75_dialog_content = "<color=#e8d9bb>You'll be able to leave in 3 minutes.</color>",
  ui_story_5015_50150601_76_dialog_content = "... Honestly speaking, I'm still surprised that you agreed to open the exit for us.",
  ui_story_5015_50150601_77_dialog_content = "You kept stressing that your top priority is to keep the city safe, and you said you didn't have any emotions.",
  ui_story_5015_50150601_78_dialog_content = "I thought you would force us to stay underground for the safety of the city.",
  ui_story_5015_50150601_79_dialog_content = "<color=#e8d9bb>I protected the city to keep our civilization alive.</color>",
  ui_story_5015_50150601_80_dialog_content = "<color=#e8d9bb>Since the residents are all gone... All this metal, concrete, dust, and even us are now useless.</color>",
  ui_story_5015_50150601_81_dialog_content = "<color=#e8d9bb>According to my calculations, keeping you here and making you face the earthquakes, Eclipsites, and unstable power source...</color>",
  ui_story_5015_50150601_82_dialog_content = "<color=#e8d9bb>... doesn't help me complete my mission.</color>",
  ui_story_5015_50150601_83_dialog_content = "<color=#e8d9bb>Therefore, destroying myself to send you away is completely in line with my program.</color>",
  ui_story_5015_50150601_84_dialog_content = "<color=#e8d9bb>In the end, it's a pity that we were unable to protect the original residents of the city.</color>",
  ui_story_5015_50150601_85_dialog_content = "No.",
  ui_story_5015_50150601_86_dialog_content = "Even if the past residents are now lost in history...",
  ui_story_5015_50150601_87_dialog_content = "Their spirit lives on in you...",
  ui_story_5015_50150601_88_dialog_content = "Your decisions and perseverance have delivered their beliefs.",
  ui_story_5015_50150601_89_dialog_content = "You have connected with us after so long and conveyed everything to us.",
  ui_story_5015_50150601_90_dialog_content = "You shouldn't have any regrets.",
  ui_story_5015_50150601_91_dialog_content = "<color=#e8d9bb>I'm glad that you acknowledge everything I've done.</color>",
  ui_story_5015_50150601_92_dialog_content = "<color=#e8d9bb>But I still have some regrets.</color>",
  ui_story_5015_50150601_93_dialog_content = "<color=#e8d9bb>We... finally welcomed a new resident, Gretel.</color>",
  ui_story_5015_50150601_94_dialog_content = "<color=#e8d9bb>But I can't accompany Gretel forever like she wants me to.</color>",
  ui_story_5015_50150601_95_dialog_content = "<color=#e8d9bb>I want you to convey my apologies to her.</color>",
  ui_story_5015_50150601_96_dialog_content = "To be honest, when it comes to this type of thing...",
  ui_story_5015_50150601_97_dialog_content = "You're acting... like a living organism that thinks and has emotions.",
  ui_story_5015_50150601_98_dialog_content = "A machine wouldn't feel sorry or regretful, right?",
  ui_story_5015_50150601_99_dialog_content = "<color=#e8d9bb>Maybe this was how I was designed in the first place.</color>",
  ui_story_5015_50150601_100_dialog_content = "<color=#e8d9bb>My design makes it seem like I have a human side to make it easier to communicate with you.</color>",
  ui_story_5015_50150601_101_dialog_content = "But at this moment, I have such a strong feeling... that you have feelings.",
  ui_story_5015_50150601_102_dialog_content = "Say, how do we define whether someone or something \"has feelings\"?",
  ui_story_5015_50150601_103_dialog_content = "<color=#e8d9bb>... Rumble...</color>",
  ui_story_5015_50150601_104_dialog_content = "What's that sound?",
  ui_story_5015_50150601_105_dialog_content = "<color=#e8d9bb>Sorry, I cannot answer your question... The exit has been opened, and it is time to bid you farewell.</color>",
  ui_story_5015_50150601_106_dialog_content = "<color=#e8d9bb>I guess it isn't appropriate to end with see you later, as this is truly our last farewell.</color>",
  ui_story_5015_50150601_107_dialog_content = "<color=#e8d9bb>I wish all of you will reach the surface safely.</color>",
  ui_story_5015_50150601_108_dialog_content = "... Butler...",
  ui_story_5015_50150601_109_dialog_content = "PlayerName, wake up now! The exit is open!",
  ui_story_5015_50150601_110_dialog_content = "Did you have a connection with the Butler again?",
  ui_story_5015_50150601_111_dialog_content = "Yes... Oh right, I have something to tell Gretel...",
  ui_story_5015_50150601_112_dialog_content = "*Sob* Sister, I-I don't want to leave.",
  ui_story_5015_50150601_113_dialog_content = "I want to go back to the Butler...",
  ui_story_5015_50150601_114_dialog_content = "Gretel... Hold my hand tight because it's time to leave.",
  ui_story_5015_50150601_115_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5015_50150601_116_dialog_content = "Is it another earthquake?",
  ui_story_5015_50150601_117_dialog_content = "We're out of time... PlayerName, Gretel, we need to leave now!",
  ui_story_5015_50150601_118_dialog_content = "Gretel, let's go!",
  ui_story_5015_50150601_119_dialog_content = "*Sob* Butler...",
  ui_story_5015_50150601_120_dialog_content = "PlayerName, watch out for the falling objects!",
  ui_story_5015_50150601_121_dialog_content = "... Phew, that was a close call. Watch out for the falling rocks!",
  ui_story_5015_50150601_122_dialog_content = "Will we make it in time if we climb up like this?",
  ui_story_5015_50150601_123_dialog_content = "What if this place really explodes like the Butler said?",
  ui_story_5015_50150601_124_dialog_content = "I really hope Soroz can pick us up.",
  ui_story_5015_50150601_125_dialog_content = "Even an airship would do... We just need something that can directly take flight.",
  ui_story_5015_50150601_126_dialog_content = "Ruby, your imagination is so unrealistic.",
  ui_story_5015_50150601_127_dialog_content = "At least the Colossus is nearby... Do you know how far away an airship is? It's not possible.",
  ui_story_5015_50150601_128_dialog_content = "An airship?",
  ui_story_5015_50150601_129_dialog_content = "Princess Carleen, you've never seen an airship even though you live in Lumopolis?",
  ui_story_5015_50150601_130_dialog_content = "No, I suddenly remembered that we really do have something that can fly...",
  ui_story_5015_50150601_131_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5015_50150601_132_dialog_content = "Is that... the sound of an explosion?",
  ui_story_5015_50150601_133_dialog_content = "Could the Alchemy stars have already...",
  ui_story_5015_50150601_134_dialog_content = "Butler!!! *Sob*",
  ui_story_5015_50150601_135_dialog_content = "Quick! Climb up and don't let go! Gretel, I'll pull you up...",
  ui_story_5015_50150601_136_dialog_content = "Move quickly, everyone! We have to leave the lower levels! The explosions have begun.",
  ui_story_5015_50150601_137_dialog_content = "We're still several hundred meters from the surface. We might not make it out before the explosions reach us...",
  ui_story_5015_50150601_138_dialog_content = "Watch out for the rocks... The collapse is getting worse!",
  ui_story_5015_50150601_139_dialog_content = "This won't do. We need a quick way to reach the surface!",
  ui_story_5015_50150601_140_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5015_50150601_141_dialog_content = "Oh no... the passage has cracked!",
  ui_story_5015_50150601_142_dialog_content = "And the crack is too big! Look at the city outside...",
  ui_story_5015_50150601_143_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5015_50150601_144_dialog_content = "Climb faster!",
  ui_story_5015_50150601_145_dialog_content = "The surface is still fine... We just need to climb to the lift...",
  ui_story_5015_50150601_146_dialog_content = "No... we can't get up. The middle part has cracked!",
  ui_story_5015_50150601_147_dialog_content = "<color=#e8d9bb>Boooom!</color>",
  ui_story_5015_50150601_148_dialog_content = "Even this section of the passage is collapsing... We're doomed!",
  ui_story_5015_50150601_149_dialog_content = "Come out now!!!",
  ui_story_5015_50150601_150_dialog_content = "What? Is that a... horse? You can summon a horse with Luminatics?",
  ui_story_5015_50150601_151_dialog_content = "Everyone, hop on now!",
  ui_story_5015_50150601_152_dialog_content = "PlayerName, Vice, grab my hand!",
  ui_story_5015_50150601_153_dialog_content = "Huff... I'm coming... up...",
  ui_story_5015_50150601_154_dialog_content = "No, Miss Siobhan, my pants are about to break...",
  ui_story_5015_50150601_155_dialog_content = "But we're in mid-air. I'll be doomed if I don't grab on tightly.",
  ui_story_5015_50150601_156_dialog_content = "Everyone under me will also be doomed!",
  ui_story_5015_50150601_157_dialog_content = "Wow, you've formed such a long trail!!!",
  ui_story_5015_50150601_158_dialog_content = "I-I didn't expect we could fly in the air like this...",
  ui_story_5015_50150601_159_dialog_content = "Carleen, can we get back to the passage on the surface?",
  ui_story_5015_50150601_160_dialog_content = "We can! The earthquakes and explosions have widened the exit...",
  ui_story_5015_50150601_161_dialog_content = "We can fly up directly!",
  ui_story_5015_50150601_162_dialog_content = "Rouge, this sure is a 5-star flying experience!",
  ui_story_5015_50150601_163_dialog_content = "It's simply too exciting!",
  ui_story_5015_50150601_164_dialog_content = "Can't you cut down on the jokes right now? Can you act more seriously?!",
  ui_story_5015_50150601_165_dialog_content = "Sigh, who would have expected that we would leave like this...",
  ui_story_5015_50150601_166_dialog_content = "Just like this, a beautiful city has...",
  ui_story_5015_50150601_167_dialog_content = "... Blown to pieces.",
  ui_story_5015_50150601_168_dialog_content = "Phew! Thank goodness we got out alive.",
  ui_story_5015_50150601_169_dialog_content = "Let's do a headcount.",
  ui_story_5015_50150601_170_dialog_content = "Did anyone get hurt?",
  ui_story_5015_50150601_171_dialog_content = "Everyone got up safely.",
  ui_story_5015_50150601_172_dialog_content = "Right, PlayerName, I, Vice, Valencia, and Gretel need to report back to Illumina...",
  ui_story_5015_50150601_173_dialog_content = "Why must they follow you back to Illumina?",
  ui_story_5015_50150601_174_dialog_content = "Nimbus clearly entrusted them to the Church of the Lumopolis.",
  ui_story_5015_50150601_175_dialog_content = "That was if no one from Illumina was there.",
  ui_story_5015_50150601_176_dialog_content = "Siobhan, you're so overbearing...",
  ui_story_5015_50150601_177_dialog_content = "You guys! Isn't the best solution to ask Valencia and Gretel where they want to go?",
  ui_story_5015_50150601_178_dialog_content = "Gretel...",
  ui_story_5015_50150601_179_dialog_content = "*Sob* Sister...",
  ui_story_5015_50150601_180_dialog_content = "This isn't real... right?",
  ui_story_5015_50150601_181_dialog_content = "Am I dreaming? Tell me this is a nightmare... *Sob*",
  ui_story_5015_50150601_182_dialog_content = "Wake me up now... Can you ask the Butler to wake me up...",
  ui_story_5015_50150601_183_dialog_content = "I still need to go to school with Guardian Angel No. 3... We said we would go on a stroll together...",
  ui_story_5015_50150601_184_dialog_content = "We were going to see who could finish one lap around the central park first...",
  ui_story_5015_50150601_185_dialog_content = "The Butler told me he found a new recipe that even you can make easily, sister...",
  ui_story_5015_50150601_186_dialog_content = "We made a deal to go fishing, and we still need to clean up mom and dad's room like always...",
  ui_story_5015_50150601_187_dialog_content = "It's so messy there right now... because the data is everywhere... I'm sure they'll be happy after we clean it up.",
  ui_story_5015_50150601_188_dialog_content = "Gretel... the city is already...",
  ui_story_5015_50150601_189_dialog_content = "*Sob* It would be nice if this was a nightmare...",
  ui_story_5015_50150601_190_dialog_content = "Why... Why did this happen...",
  ui_story_5015_50150601_191_dialog_content = "... The Butler... he prepared a new recipe?",
  ui_story_5015_50150601_192_dialog_content = "Yes... the ingredients are the fish we caught... and the plants we found last time...",
  ui_story_5015_50150601_193_dialog_content = "That must have been hard... There are only so many edible ingredients... yet he kept thinking of ways to design different meals for us.",
  ui_story_5015_50150601_194_dialog_content = "Hope we could eat better food here...",
  ui_story_5015_50150601_195_dialog_content = "I'm sure the Butler will be happy to know that you'll be eating meals on time every day and won't be a picky eater anymore...",
  ui_story_5015_50150601_196_dialog_content = "*Sob* I... I won't be a picky eater anymore...",
  ui_story_5015_50150601_197_dialog_content = "I really want the Butler to be here with us...",
  ui_story_5015_50150601_198_dialog_content = "It would have been great if the Butler was a person... Then it could have left with us...",
  ui_story_5015_50150601_199_dialog_content = "It would be able to stand here with us...",
  ui_story_5015_50150601_200_dialog_content = "Gretel, you've still got me. I'll always be here for you...",
  ui_story_5015_50150601_201_dialog_content = "Boo-hoo...",
  ui_story_5015_50150601_202_dialog_content = "I wonder... what would mom and dad think if they knew that we returned to the world they used to live in.",
  ui_story_5015_50150601_203_dialog_content = "We met their companions from the past, and we survived a crisis together.",
  ui_story_5015_50150601_204_dialog_content = "We protected each other. We finally drummed up the courage to come to this real land.",
  ui_story_5015_50150601_205_dialog_content = "We can look at... real sky.",
  ui_story_5015_50150601_206_dialog_content = "What about wars? Are there still wars?",
  ui_story_5015_50150601_207_dialog_content = "Are there also many Eclipsites here?",
  ui_story_5015_50150601_208_dialog_content = "That doesn't matter because we'll still together, Gretel.",
  ui_story_5015_50150601_209_dialog_content = "Sister...",
  ui_story_5015_50150601_210_dialog_content = "I'll find us a new home. Trust me.",
  ui_story_5015_50150601_211_dialog_content = "As long as we are together, anywhere can be our home.",
  ui_story_5015_50150601_212_dialog_content = "... As long as I'm with my sister... then I have a home...",
  ui_story_5015_50150601_213_dialog_content = "(It looks like Gretel has calmed down...)",
  ui_story_5015_50150601_214_dialog_content = "(It's possible that not everything was destroyed... We still have the coordinates and information, so Illumina can still excavate it.)",
  ui_story_5015_50150601_215_dialog_content = "(But I can't say that directly right now.)",
  ui_story_5015_50150601_216_dialog_content = "(Or else Gretel might do something impulsive. Not to mention that Florine and the others are here...)",
  ui_story_5015_50150601_217_dialog_content = "What are you thinking, Miss Siobhan?",
  ui_story_5015_50150601_218_dialog_content = "Ahem, nothing. Let's ask Valencia and Gretel what their plans are for the future.",
  ui_story_5015_50150601_219_dialog_content = "Valencia, Gretel, do you want to go to Umbraton? I can show you around the place.",
  ui_story_5015_50150601_220_dialog_content = "Maybe... I haven't made up my mind yet, so I can follow you for a while.",
  ui_story_5015_50150601_221_dialog_content = "I mean, now it's our turn to be outsiders...",
  ui_story_5015_50150601_222_dialog_content = "Right, Ruby, do we have any money?",
  ui_story_5015_50150601_223_dialog_content = "We'll need to buy them some things after we get there...",
  ui_story_5015_50150601_224_dialog_content = "Florine and I can...",
  ui_story_5015_50150601_225_dialog_content = "Oh, we have our own intentions too... Do you think we need to worry about money? Look!",
  ui_story_5015_50150601_226_dialog_content = "I... am I hallucinating?",
  ui_story_5015_50150601_227_dialog_content = "You can stop rubbing your eyes now. This is all real.",
  ui_story_5015_50150601_228_dialog_content = "I picked up all of this while we were leaving...",
  ui_story_5015_50150601_229_dialog_content = "Droid parts, cans, tool components... and ancient outfits!",
  ui_story_5015_50150601_230_dialog_content = "We can sell these for a lot of money in Umbraton!",
  ui_story_5015_50150601_231_dialog_content = "Rouge, we're going to be rich!",
  ui_story_5015_50150601_232_dialog_content = "Ruby, how can you say that at a time like this...",
  ui_story_5015_50150601_233_dialog_content = "Ahem, Valencia, Gretel, I actually took all of these for you.",
  ui_story_5015_50150601_234_dialog_content = "Yeah! These belonged to you. Do you want to keep some of them as souvenirs?",
  ui_story_5015_50150601_235_dialog_content = "What Ruby means is that all the things here are yours...",
  ui_story_5015_50150601_236_dialog_content = "... Stop explaining... Do you think I don't understand?",
  ui_story_5015_50150601_237_dialog_content = "We'll take these clothes. You can have the rest...",
  ui_story_5015_50150601_238_dialog_content = "Phew... That's great! You're quite generous!",
  ui_story_5015_50150601_239_dialog_content = "...",
  ui_story_5015_50150601_240_dialog_content = "Valencia, Gretel, do you want to take Rouge's suggestion and go to Umbraton?",
  ui_story_5015_50150601_241_dialog_content = "Gretel, what do you say? Where do you want to go first?",
  ui_story_5015_50150601_242_dialog_content = "I'm happy as long as I'm with you, sister...",
  ui_story_5015_50150601_243_dialog_content = "Oh right, Gretel. I wasn't able to convey the Butler's message to you before because of the earthquake.",
  ui_story_5015_50150601_244_dialog_content = "Do you want to hear it now?",
  ui_story_5015_50150601_245_dialog_content = "O-of course!",
  ui_story_5015_50150601_246_dialog_content = "The Butler said he regrets that he can't keep accompanying you.",
  ui_story_5015_50150601_247_dialog_content = "And he wanted me to convey his apologies to you.",
  ui_story_5015_50150601_248_dialog_content = "... Okay, I got it.",
  ui_story_5015_50150601_249_dialog_content = "Oh, Gretel, why are your eyes red? Is there sand...",
  ui_story_5015_50150601_250_dialog_content = "Ruby, lay off the lame jokes right now.",
  ui_story_5015_50150601_251_dialog_content = "Ah... I'm sorry.",
  ui_story_5015_50150601_252_dialog_content = "Valencia, Gretel, this is my communicator... Hold on to it.",
  ui_story_5015_50150601_253_dialog_content = "You don't need to give me one. I have my father's communicator, so I can communicate with you.",
  ui_story_5015_50150601_254_dialog_content = "I know, but I still want you to take mine. It's safer to have one more.",
  ui_story_5015_50150601_255_dialog_content = "Also, if you have this, you can keep your father's relic safe...",
  ui_story_5015_50150601_256_dialog_content = "Just use the communicator I gave you if you want to contact anyone in the future.",
  ui_story_5015_50150601_257_dialog_content = "Also, I want to bring your father's diary with me back to Illumina. Would you...",
  ui_story_5015_50150601_258_dialog_content = "Oh, yes, you can take it... Thank you.",
  ui_story_5015_50150601_259_dialog_content = "... I agree with my sister...",
  ui_story_5015_50150601_260_dialog_content = "Okay, if you ever want to come back, just let me know.",
  ui_story_5015_50150601_261_dialog_content = "Illumina will always welcome you with open arms.",
  ui_story_5015_50150601_262_dialog_content = "The same goes for the Church of the Lumopolis.",
  ui_story_5015_50150601_263_dialog_content = "Everyone, do you need me to give you a lift with the Colossus?",
  ui_story_5015_50150601_264_dialog_content = "We'll go to Lumopolis and Umbraton first, then Illumina... We can also fly to the Rediesel Desert.",
  ui_story_5015_50150601_265_dialog_content = "Great! Rouge, Valencia, Gretel, let's take a tour of PlayerName's Colossus now!",
  ui_story_5015_50150601_266_dialog_content = "Colossus? Is it the Colossus the Butler spoke of?",
  ui_story_5015_50150601_267_dialog_content = "Do you want to know? Just follow me!",
  ui_story_5015_50150601_268_dialog_content = "Miss Siobhan, let's go!",
  ui_story_5015_50150601_269_dialog_content = "Then I'll catch a ride with you... I still want to chat with Valencia and the others along the way.",
  ui_story_5015_50150601_270_dialog_content = "Florine, Erica, what about you?",
  ui_story_5015_50150601_271_dialog_content = "We gladly accept your invitation, Princess Carleen.",
  ui_story_5015_50150601_272_dialog_content = "Let's go then... We'll start a new adventure with Valencia and Gretel.",
  ui_story_5015_50150601_273_dialog_content = "I received a set of mysterious signals and accidentally discovered the ancient ruins...",
  ui_story_5015_50150601_274_dialog_content = "... Upon verification, the mysterious signal was sent by the missing Illumina researcher, Seamus, before his death...",
  ui_story_5015_50150601_275_dialog_content = "... The ruins are located underground. It looks like a civilian refuge city...",
  ui_story_5015_50150601_276_dialog_content = "... The ruins no longer have any residents. The reason for their disappearance is unknown. I speculate that the reason for this is an Eclipsite invasion...",
  ui_story_5015_50150601_277_dialog_content = "... Seamus' children, Valencia and Gretel, were living under the care of an artificial intelligence called the Butler...",
  ui_story_5015_50150601_278_dialog_content = "... I have obtained all the research data left behind by Seamus. This will be of great benefit to future research...",
  ui_story_5015_50150601_279_dialog_content = "... As there wasn't enough time, I couldn't obtain information about artificial intelligence...",
  ui_story_5015_50150601_280_dialog_content = "... I was also unable to save the Alchemy stars, the power source that was at the brink of destruction...",
  ui_story_5015_50150601_281_dialog_content = "... We will decide whether to excavate the ruins after studying Seamus' data...",
  ui_story_5015_50150601_282_dialog_content = "... Seamus served Illumina with all his heart and soul...",
  ui_story_5015_50150601_283_dialog_content = "... Even in a desperate situation, he did not give up on finding a path of survival for the future generation...",
  ui_story_5015_50150601_284_dialog_content = "... His actions in the ruins showed the noble spirit of Illumina. He is an example to us all...",
  ui_story_5015_50150601_285_dialog_content = "... That's all for my report.",
  ui_story_5015_50150601_286_dialog_content = "... Splendor Illumina!",
  ui_story_5015_50150601_287_dialog_content = "... Nimbus rebuilt her faith in the God of Light and reflected profoundly...",
  ui_story_5015_50150601_288_dialog_content = "... In the written documents she left behind, Nimbus entrusted her two daughters to the church...",
  ui_story_5015_50150601_289_dialog_content = "... I think that, out of the kindness of the God of Light, the church should shelter the two girls...",
  ui_story_5015_50150601_290_dialog_content = "... Many of the artificial intelligences in the ruins have already stopped functioning...",
  ui_story_5015_50150601_291_dialog_content = "... The artificial intelligence responsible for the biological module modified many Eclipsites and was our most dangerous enemy in the ruins...",
  ui_story_5015_50150601_292_dialog_content = "... The admonition of the God of Light has been proven...",
  ui_story_5015_50150601_293_dialog_content = "... The artificial intelligence of the ruins and the power source, Alchemy stars, have been destroyed by the explosions...",
  ui_story_5015_50150601_294_dialog_content = "... Although the Illumina researcher Siobhan took away Seamus' research data...",
  ui_story_5015_50150601_295_dialog_content = "... Seamus never got close to the most sinister secret at the heart of the ruins...",
  ui_story_5015_50150601_296_dialog_content = "... This ancient threat has now been buried under the dust and rocks forever...",
  ui_story_5015_50150601_297_dialog_content = "... That's all for now.",
  ui_story_5015_50150601_298_dialog_content = "... White Night up high.",
  ui_story_5015_50150601_299_dialog_content = "Soroz, I wonder if you can give me an answer if you can still hear me.",
  ui_story_5015_50150601_300_dialog_content = "Is it really impossible for artificial intelligence to develop feelings?",
  ui_story_5015_50150601_301_dialog_content = "I recently met an artificial intelligence that can communicate with me via a telepathic connection, just like you.",
  ui_story_5015_50150601_302_dialog_content = "It was the guardian of an ancient underground city.",
  ui_story_5015_50150601_303_dialog_content = "In the end, it chose to sacrifice itself to let us escape, but it didn't seem to understand feelings.",
  ui_story_5015_50150601_304_dialog_content = "It thought that all its actions were predetermined by its program.",
  ui_story_5015_50150601_305_dialog_content = "But I don't believe that.",
  ui_story_5015_50150601_306_dialog_content = "All that care, trust, and comfort during the time they spent together... could those all because of settings?",
  ui_story_5015_50150601_307_dialog_content = "It was even willing to sacrifice itself to save others... Did it really do that to complete its mission?",
  ui_story_5015_50150601_308_dialog_content = "If those aren't examples of feelings, what are feelings?",
  ui_story_5015_50150601_309_dialog_content = "If I deny all this, then how was I living before I became seventeen?",
  ui_story_5015_50150601_310_dialog_content = "... We were quite lucky to be able to escape the undercity with all our companions and those two sisters.",
  ui_story_5015_50150601_311_dialog_content = "Other than the Butler, I must also thank the parents of those two sisters.",
  ui_story_5015_50150601_312_dialog_content = "I can't imagine the price they paid so that their daughters could survive...",
  ui_story_5015_50150601_313_dialog_content = "Soroz, surely my parents also did everything they could so that I could survive, right?",
  ui_story_5015_50150601_314_dialog_content = "...",
  ui_story_5015_50150601_315_dialog_content = "When will I be able to hear your answers again?"
}
return config
